       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6fd31dae-451a-5dc7-8700-063f8a3fe843","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -سيارة دون قبض كامل الثمن -قيام املشتري (املدعى عليه) بتحويل البائع (املدعى) على آخر له دين يف ذمته -إعسار احملال عليه -الرجوع بالدين على احمليل -عدم صحة احلوالة وإلزام املدعى عليه بدفع باقي الثمن .","document_number":"33394384","case_number":"32604132","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/26","year":"1434","subject":"بيع -سيارة دون قبض كامل الثمن -قيام املشتري (املدعى عليه) بتحويل البائع (املدعى) على آخر له دين يف ذمته -إعسار احملال عليه -الرجوع بالدين على احمليل -عدم صحة احلوالة وإلزام املدعى عليه بدفع باقي الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/8/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33394384 :‬‬\n                   ‫َر ْق ُم الدعوى‪32604132 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34217641‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫بيــع ‪ -‬ســيارة دون قبــض كامــل الثمــن ‪ -‬قيــام املشــتري (املدعــى عليــه)‬\n‫بتحويــل البائــع (املدعــى) علــى آخــر لــه ديــن يف ذمتــه ‪ -‬إعســار احملــال‬\n‫عليــه ‪ -‬الرجــوع بالديــن علــى احمليــل ‪ -‬عــدم صحــة احلوالــة وإلــزام‬\n                                           ‫املدعــى عليــه بدفــع باقــي الثمــن ‪.‬‬\n\n\n\n\n‫‪ -‬مــا قــرره الفقهــاء كمــا يف الــروض املربــع ( وإذا كان احملــال عليــه‬\n‫مفلســا أو غيــر ملــيء ولــم يكــن احملتــال رضــي رجــع بدينــه علــى احمليــل‬\n‫وامللــيء هــو القــادر علــى الوفــاء غيــر املماطــل وميكنــه حضــوره ملجلــس‬\n                                                                     ‫احلكــم ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه بــاع ســيارة ذكــر وصفهــا للمدعــى عليــه ‪ ،‬حــول‬\n‫املدعــى عليــه املدعــي علــى شــخص آخــر ‪ ،‬اشــترط املدعــي أن يكــون‬\n‫احملـ ــال عليه غير معسر ‪ ،‬قبـ ــل احملال عليه احلـ ــوالة ‪ ،‬تبني أن للم ــحال‬\n‫عليــه دعــوى إع ــسار وال ميكنــه الســداد ‪ ،‬طلــب املدعــي إلـ ــزام املدعــى‬\n‫عليــه بدفــع املبلــغ ‪ ،‬صـ ــادق املدعــى عليــه علــى الدعـ ــوى ودفــع بــأن‬\n‫احملـ ــال عل ـيـ ــه غيــر معســر ومتــى مــا صــدر صـ ــك بإعســار احمل ـ ــال عليــه‬\n‫فـل ــه الرجـ ــوع حينئذ عليه ‪ ،‬ملا سبـ ــق م ــن الدعوى واإلجـ ــابة وم ــا قـ ــرره‬\n\n                                                                                          ‫‪28‬‬\n\f     ‫الفقهــاء كمــا يف الــروض املربــع ‪( :‬وإذا كان احملــال عليــه مفلس ـ ًا أو‬\n     ‫غيــر ملــيء ولــم يكــن احملــال رضــي‪ ،‬رجــع بدينــه علــى احمليــل‪ ،‬وامللــيء‬\n     ‫هــو القــادر علــى الوفــاء غيــر املماطــل وميكنه حضــوره ملجلس احلكم)‪،‬‬\n     ‫ص ــدر احلكــم بعــدم صحــة احلـ ــوالة وإلــزام املدعــى عليــه بدفـ ــع املبلــغ‬\n     ‫املدعــى بــه ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                            ‫االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 32604132‬وتاريــخ ‪1432/12/25‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 321625182‬وتاريــخ ‪1432/12/25‬ه ـ ففــي‬\n     ‫يــوم االثنــن املوافــق ‪1433/08/26‬ه ـ حضــر ‪ ...............‬ســعودي مبوجب‬\n     ‫الســجل املدنــي رقــم ‪ ...........‬وادعــى علــى احلاضــر معــه ‪ ..............‬ســعودي‬\n     ‫مبوجــب ســجل مدنــي رقــم ‪ ...........‬قائــا يف حتريــر دعــواه عليه لقد بعت‬\n     ‫ســيارة بثمــن وقــدره مائــه وخمســه وســبعون ألــف ريــال منهــا ســبعون ألف‬\n     ‫مقــدم ومائــه وخمســه االف ريــال حولنــي علــى ‪ ................‬واشــترطت‬\n     ‫عليــه ان ال يكــون احملــال عليــه معســرا وقــد حضــر ‪ ...............‬وقبــل‬\n     ‫احلوالــة وتبــن بعــد ذلــك ان لــه معاملــة اعســار وانــه ال ميكنــه الســداد‬\n     ‫لــذا أطلــب إلــزام املدعــى عليــه بدفــع مائــه وخمســه االف ريــال هــذه‬\n     ‫دعــواي وبســؤال املدعــى عليــه قــال صحيــح اشــتريت الســيارة املذكــورة‬\n     ‫وبقــي مائــه وخمســه االف ريــال وحولتــه بهــا علــى ‪ ......‬واشــترط عليــه‬\n     ‫مالءتــه و‪ ..............‬ليــس مبعســور وميكنــه مطالبتــه بنفســه إن رغــب‬\n\n‫‪29‬‬\n\f‫هكــذا قــال وبســؤالهما متــى متــت احلوالــة قــال قبــل ســنتني وقــال املدعــى‬\n‫عليــه لقــد صــدر لــي حكــم علــى املدعــو ‪ ................‬برقــم ‪ 37/65‬يف‬\n‫‪1429/05/08‬ه ـ ولــم أســجنه أو اطالــب بتنفيــذه ولكني حولت املدعى‬\n‫عليــه وهــو لــم يســدد الصــك املذكــور و إذا صــدر لــه صــك إعســار فلــه‬\n‫الرجــوع علــى وبعرضــه علــى املدعــي قــال لقــد راجعــت احلقــوق وقالــوا‬\n‫أنــه ال يصــدر إعســار إال بعــد الســجن وهــو لــم يســجن هكــذا قــال فبنــاء‬\n‫علــى مــا تقــدم وملــا قــرره الفقهــاء كمــا يف الــروض املربــع ( وإذا كان‬\n‫احملــال عليــه مفلســا أو غيــر ملــيء ولــم يكــن احملتــال رضــي رجــع بدينــه‬\n‫علــى احمليــل وامللــيء هــو القــادر علــى الوفــاء غيــر املماطــل وميكنــه‬\n‫حضــوره ملجلــس احلكــم ) لذلــك كلــه فقــد افهمــت الطرفــن بعــدم‬\n‫صحــة احلوالــة وألزمــت املدعــى عليــه ‪ .............‬بدفــع مبلــغ وقــدره مائــه‬\n‫وخمســه االف ريــال للمدعــي وبــه حكمــت وبعرضــه علــى عليهمــا قــرر‬\n‫املدعــي القناعــة وقــرر املدعــى عليــه املعارضــة وطلب االســتئناف فأجيب‬\n‫لطلبــه وســلم صــورة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا‬\n‫فــإن مضــت املــدة ولــم يتقــدم بالئحــة اعتراضيــه عليــه ســقط حقــه يف‬\n‫االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/26‬هـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/4/21‬ه ـ‬\n‫فتحــت اجللســة الســاعة الثامنــة والنصــف وكانــت املعاملــة قــد عــادت‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 33474158‬وتاريــخ‬\n‫‪1433/12/20‬ه ـ املتضمــن أنــه لوحــظ أنــه ذكــر املدعــي بــأن احملــال‬\n‫عليــه لــه معاملــة إعســار وال ميكنــه الســداد ولــم جنــد فضيلتــه تأكــد‬\n‫مــن ذلــك مبخاطبــة اجلهــة املختصــة يف ذلــك وال بــد مــن ذلــك واهلل املوفــق‬\n\n\n                                                                                      ‫‪30‬‬\n\f     ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم واملوقــع مــن أصحــاب‬\n     ‫الفضيلــة القضــاة مبحكمــة االســتئناف فضيلــة الشــيخ ‪..................‬‬\n     ‫وفضيلــة الشــيخ ‪ ..........‬ورئيــس الدائــرة فضيلــة الشــيخ ‪ ..........‬أ ‪ .‬ه ـ‬\n     ‫عليــه فــإن املدعــى عليــه صــادق علــى اشــتراط مــاءة احملــال عليــه ومــن‬\n     ‫شــروط لــزوم احلوالــة عنــد الفقهــاء املــاءة وامللــيء هــو القــادر علــى الوفاء‬\n     ‫غيــر املماطــل واحملــال عليــه يف القضيــة ممتنــع عــن الســداد حيــث يقــر‬\n     ‫املدعــى عليــه باســتصدار حكــم وانــه لــم ينفــذه ولــذا فهــو غيــر ملــيء‬\n     ‫وال حاجــة ملعرفــة صــدور حكــم بإثبــات إعســاره ألن الشــرط هــو املــاءة‬\n     ‫وليــس عــدم االفــاس وهــذا ملحــظ احلكــم فليــس لــدي ســوى مــا‬\n     ‫أجريــت و قــررت إحلــاق مــا ســبق وإعادتــه حملكمــة االســتئناف حيــث‬\n     ‫ليــس لــدي ســوى مــا أجريتــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                     ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/4/21‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 32604132‬وتاريــخ ‪ 1432/12/25‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 321625182‬وتاريــخ ‪ 1432/12/25‬ه ـ ففــي‬\n     ‫يــوم االثنــن املوافــق‪ 1434/06/05‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n     ‫وخمســة وعشــرين دقيقــة هــذا وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بالريــاض مبوجــب خطــاب رئيــس محكمــة االســتئناف‬\n     ‫بالريــاض املســاعد برقــم ‪ 341150486‬يف ‪1434/5/27‬ه ـ ومشــفوعة‬\n     ‫قــرار تصديــق صــادر مــن الدائــرة احلقوقيــة اخلامســة برقــم ‪34217641‬‬\n     ‫يف ‪1434/5/20‬ه ـ الــذي جــاء فيــه أنــه لــم يظهــر مــا يوجــب االعتــراض‬\n     ‫علــى احلكــم وعليــه فقــد امــرت بتنفيــذ احلكــم واكمــال الــازم وبــاهلل‬\n\n\n‫‪31‬‬\n\f‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n             ‫حــرر يف ‪ 1434/06/05‬ه ـ والســاعة التاســعة وثالثــون دقيقــة‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم االثنــن املوافــق‪ 1434/06/12‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 0915‬وفيهــا حضــر املدعــي ‪ ..............‬املدون هويته ســابقا وقرر‬\n‫اســتالمه لكامــل املبلــغ احملكــوم بــه وقــدره مائــة وخمســة االف ريــال‬\n‫وآخــره مبلغـ ًا قــدره عشــرون الــف ريــال مبوجــب الشــيك املســحوب علــى‬\n‫مصــرف الراجحــي برقــم ‪ 237222‬يف ‪1434/06/11‬ه ـ ألمــر ‪.............‬‬\n‫كمــا قــرر انــه لــم يعــد لــه ال دعــوى وال طلــب يف ذمــة املدعــى عليــه‬\n‫وتكــون القضيــة منتهيــة وجــرى حتريــره والتهميــش مبوجبــه وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/06/12‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":28,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d539f8df27f53177ef193a3b1083102a28baf0afcb5d7b2171995aad906d770","normalized_text_hash":"7f56f0ff6cdd41167d434af1e330b13efbe7bfd6cdc4de6aa7e7674d15d2f429","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p28-33394384"},{"id":"0295afae-b1c0-585d-b9bd-72f76531f4e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -إبل -رد مازدا عن الثمن احلقيقي للمبيع للغن -تصرف املشترى يف املبيع دالله الرضا يسقط به خيار الغن -احلكم بصرف النظر عن الدعوى .","document_number":"33429922","case_number":"32612060","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/17","year":"1434","subject":"بيع -إبل -رد مازدا عن الثمن احلقيقي للمبيع للغن -تصرف املشترى يف املبيع دالله الرضا يسقط به خيار الغن -احلكم بصرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/10/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33429922 :‬‬\n                         ‫َر ْق ُم الدعوى‪32612060 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3432028‬تاريخه‪1434/2/6 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬إبــل ‪ -‬رد مــازدا عــن الثمــن احلقيقــي للمبيــع للغــن ‪ -‬تصــرف‬\n      ‫املشــترى يف املبيــع داللــه الرضــا يســقط بــه خيــار الغــن ‪ -‬احلكــم‬\n                                             ‫بصــرف النظــر عــن الدعــوى ‪.‬‬\n\n\n\n\n      ‫قــول ابــن قدامــة يف املغنــي‪« :‬ويف تصــرف املشــتري يف املبيــع مــدة اخليــار‬\n      ‫ببيــع ونحــوه فهــو يــدل علــى الرضــاء املبطــل للخيــار حيــث إن اخليــار‬\n                                 ‫يبطــل بالتصريــح بالرضــاء أو ممــا يــدل عليــه» ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن موكلــه اشــترى مــن املدعــى عليــه العــدد‬\n      ‫املذكــور يف دعــواه مــن اإلبــل وســلمه ثمنهــا ثــم اتضــح ملوكلــه بعــد‬\n      ‫ســؤال أهــل اخلبــرة أنــه يوجــد غــن كبيــر يف ســعر اإلبــل فراجــع املدعــى‬\n      ‫عليــه بعــد عشــرة أيــام مــن الشــراء وطلــب منــه اســتالم اإلبــل ورد جــزء‬\n      ‫مــن الثمــن الــذي ســلمه لــه ووعــده بــأن يتنــازل لــه عــن الباقــي مــن الثمــن‬\n      ‫إال أن املدعــى عليــه رفــض ذلــك‪ ،‬لــذا طلــب احلكــم علــى املدعــى عليــه‬\n      ‫بإعــادة املبلــغ الزائــد عــن قيمــة املثــل لإلبــل محــل الدعــوى ‪ ،‬أقــر املدعــى‬\n      ‫عليــه بأنــه بــاع املدعــي اإلبــل املذكــورة ودفــع بــأن القيمــة ليــس فيهــا‬\n      ‫غــن وهــي قيمــة الســوق وأن املدعــي قبــل أن يشــتري منــه اإلبــل طلــب‬\n\n‫‪33‬‬\n\f‫مهلــة خمســة عشــر يومــا للمشــاورة ثــم رجــع بعــد ذلــك وقــرر الشــراء‬\n‫واســتلم اإلبــل‪ ،‬املدعــي بــاع اإلبــل محــل الدعــوى وتصــرف املشــتري‬\n‫يف املبيــع مــدة اخليــار ببيــع ونحــوه يــدل علــى الرضــا ويبطــل بــه اخليــار‪،‬‬\n‫قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل‬\n‫املدعــى عليــه منهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي‪،‬‬\n                   ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ )....‬القاضــي باحملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 32612060‬وتاريــخ ‪1432/12/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 321645130‬وتاريــخ ‪1432/12/27‬ه ـ ففــي يــوم‬\n‫االثنني املوافق ‪1433/6/2‬هـ حضر (‪ )....‬سجل مدني رقم (‪ )....‬بصفته‬\n‫وكيــا عــن (‪ )....‬بالوكالــة الصــادرة مــن كتابــة عــدل املزاحميــة برقــم‬\n‫‪ 38‬يف ‪1432/11/28‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة واالقــرار‬\n‫واالنــكار وادعــى علــى احلاضــر معــه (‪ )....‬ســجل مدنــي رقــم (‪ )....‬قائــا‬\n‫يف حتريــر دعــواه إن موكلــي اشــترى مــن هــذا احلاضــر معــي يف املجلــس‬\n‫الشــرعي عــدد اثنــن وســتني ناقــة (وضــح) مببلــغ اجمالــي قــدره مليــون‬\n‫ومئتــان وأربعــون ألــف اســتلمها املدعــى عليــه وقــد اتضــح ملوكلــي بعــد‬\n‫ســؤال أهــل اخلبــرة انــه يوجــد غــن كبيــر يف ســعر اإلبــل وأن ســعرها‬\n‫احلقيقــي ال يتجــاوز ســتمائة ألــف ريــال وقــد راجــع موكلــي املدعــى‬\n‫عليــه بعــد عشــرة أيــام مــن الشــراء وطلــب منــه رد مليــون ريــال واســتالم‬\n‫اإلبــل ويتنــازل عــن مئتــن وأربعــن ألــف ريــال إال أنــه رفــض ذلــك لــذا‬\n\n                                                                                       ‫‪34‬‬\n\f     ‫أطلــب احلكــم علــى املدعــى عليــه بإعــادة املبلــغ الزائــد عــن قيمــة اإلبــل‬\n     ‫وقــدره ســتمئة وأربعــون ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليــه‬\n     ‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة مــن ناحيــة الغــن فهــذا غيــر‬\n     ‫صحيــح والصحيــح ان املدعــي اشــترى منــي اإلبــل قبــل حوالــي ســنة‬\n     ‫وثمانيــة أشــهر قيمــة الناقــة عشــرين ألــف ريــال وقــد طلــب مهلــة خمســة‬\n     ‫عشــر يومــا للمشــاورة بعــد أن أعطانــي العربــون ثــم رجــع بعــد ذلــك وقــرر‬\n     ‫الشــراء واســتلم اإلبــل وحــول املبلــغ يف حســابي والقيمــة ليــس فيهــا غــن‬\n     ‫وهــي قيمــة الســوق يف وقتــه كمــا ان املدعــي قــد بــاع عــدد مــن اإلبــل يف‬\n     ‫الســوق بعشــرين ألــف وبعضهــا وبخمســة وثالثــن ألــف ريــال لــذا فليــس‬\n     ‫لــه يف ذمتــي حــق هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة‬\n     ‫قــال أطلــب مهلــة ملراجعــة موكلــي وســؤاله عــن مــا ذكــره املدعــى عليــه‬\n     ‫هكــذا أجــاب ثــم إنــه يف يــوم االثنــن املوافــق ‪1433/10/16‬ه ـ حضــر‬\n     ‫املدعــى عليــه واملــدون بياناتــه يف اجللســة الســابقة وحضــر املدعــي أصالــة‬\n     ‫(‪ )....‬ســعودي بالســجل املدنــي رقــم (‪ )....‬وجــرى ســؤال املدعــي أصالــة‬\n     ‫عــن اإلبــل فقــرر بقولــه إن اإلبــل قــد بعتهــا جميعــا ولــم يبقــى فيهــا شــيء‬\n     ‫بعتهــا يف شــهر ربيــع االول عــام ‪1432‬ه ـ بعــد شــهر مــن شــرائها وبقــي‬\n     ‫بعيــر واحــد بعتــه بعــد ســتة أشــهر بأربعــة آالف ريــال هكــذا أجــاب‬\n     ‫فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى واالجابــة وحيــث أقــر املدعــى‬\n     ‫بالتصــرف باإلبــل ببيعهــا والتصــرف فيهــا وهــذا العمــل منــه مســقط حلــق‬\n     ‫خيــار الغــن حيــث نــص الفقهــاء رحمهــم اهلل علــى ذلــك قــال ابــن قدامــه‬\n     ‫رحمــه اهلل يف املغنــي‪« :‬ويف تصــرف املشــتري يف املبيــع مــدة اخليــار ببيــع‬\n     ‫ونحــوه فهــو يــدل علــى الرضــاء املبطــل للخيــار حيــث إن اخليــار يبطــل‬\n     ‫بالتصريــح بالرضــاء أو ممــا يــدل عليــه» لــذا فقــد حكمــت بصــرف‬\n\n\n‫‪35‬‬\n\f‫النظــر عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه وبعــرض احلكــم‬\n‫علــى أطــراف الدعــوى قنــع بــه املدعــى عليــه ولــم يقنــع بــه املدعــى وطلــب‬\n‫رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة وأفهمتــه مبراجعتنــا‬\n‫خــال عشــرة أيــام الســتالم نســخة مــن احلكــم وإعــداد الئحــة يف مــدة‬\n‫ال تتجــاوز ثالثــن يومــا مــن االســتالم وإذا لــم يقــدم الئحــة ســقط حقــه‬\n‫يف االعتــراض طبقــا للمــادة ‪178‬مــن نظــام املرافعــات الشــرعية وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                             ‫يف ‪1433/10/16‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/3/2‬ه ـ وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف مــزودة بقرارهــا رقــم ‪ 3432028‬يف‬\n‫‪1434/2/6‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى‬\n                    ‫اهلل وســلم علــى نبينــا محمــد صلــى اهلل عليــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪36‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":33,"source_page_end":36,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"129eaaf837c9d7cfe2c8d9ae932a0abae761d9fbe1f619c5e881b1b7ed96f0fd","normalized_text_hash":"3372bc7ed4a5c4bfa54218d18d07a26f6a2a9bb2cb684194b70a157a068fc8ed","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p33-33429922"},{"id":"3c708419-f480-53c4-816b-168508bbd383","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -فسخ عقد بيع -تخلف املدعى عليه مع تبلغه باحلضور -تشرع اليمن يف جانب أقوى املتداعين -حكم بتسليم مبلغ - اعتبار احلكم حضوري ا .","document_number":"34253738","case_number":"33219657","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/27","year":"1434","subject":"بيع -فسخ عقد بيع -تخلف املدعى عليه مع تبلغه باحلضور -تشرع اليمن يف جانب أقوى املتداعين -حكم بتسليم مبلغ - اعتبار احلكم حضوري ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/27 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34253738 :‬‬\n                        ‫َر ْق ُم الدعوى‪33219657 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34325090‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬فســخ عقــد بيــع ‪ -‬تخلــف املدعــى عليــه مــع تبلغــه باحلضــور‬\n     ‫‪ -‬تشــرع اليمــن يف جانــب أقــوى املتداعيــن ‪ -‬حكــم بتســليم مبلــغ ‪-‬‬\n                                                  ‫اعتبــار احلكــم حضوري ـ ًا ‪.‬‬\n\n\n\n\n                                            ‫املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم الــذي‬\n     ‫تبلــغ مبوعــد اجللســة لشــخصه ومضمــون الدعــوى ان املدعــى قــد اشــتري‬\n     ‫مــن املدعــى عليــه ارضــا موصوفــه يف نــص القضيــة مببلــغ قــدره خمســة‬\n     ‫ا وانــه عنــد حضــوره‬  ‫وعشــرون الــف ريــال اســتلمه املدعــى عليــه كام ـ ً‬\n     ‫ملعاينــة األرض واســتالمها رفــق املدعــى عليــه حضــر لهمــا اثنــان مــن‬\n     ‫ابنــاء عمومــة املدعــى عليــه ونازعــاه يف االرض وذكــرا لــه بــان املدعــى‬\n     ‫عليــه بــاع مــا ال ميلــك ثــم بعــد مداولــة اســتعد املدعــى عليــه بــان يكتــب‬\n     ‫لــه ســند ًا باملبلــغ الــذي اســتلمه مقابــل فســخ البيــع وقــام بتحريــر الســند‬\n     ‫والتــزم بالســداد خــال ســنة مــن تاريــخ حتريــر الســند ولــم يســدد منــه‬\n     ‫شــيئا وطلــب احلكــم علــى املدعــى عليــة بإلزامــه بســداد املبلــغ ‪ -‬ابــرز‬\n     ‫املدعــي بينتــه وهــي ســند ًا يتضمــن اقــرار ًا منســوب ًا للمدعــى عليــة بانــه‬\n\n‫‪37‬‬\n\f‫اقتــرض مــن املدعــي مبلغــا قــدرة خمــس وعشــرون ألــف ريــال التــزم‬\n‫بســداده ‪ .‬قــرر أنــه ليــس لديــة بينــة ســوى مــا قــدم ‪ ،‬جــرى عــرض اليمــن‬\n‫عليــه فاســتعد باحللــف وحلــف علــى صحــة دعــواه ‪ ،‬صــدر احلكــم علــى‬\n‫املدعــى عليــه بتســليم املدعــي املبلــغ املدعــى بــه واحلكــم يف حــق املدعــى‬\n‫عليــه يعــد حضوريـ ًا ومت ارســال نســخة مــن احلكــم للمدعــى عليه حســب‬\n‫النظــام ‪ .‬قــررت محكمــة االســتئناف مبكــة املكرمــة باملوافقــة علــى‬\n                                                                        ‫احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 33219657‬وتاريــخ ‪ 1433/03/28‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33584070‬وتاريــخ ‪ 1433/03/28‬ه ـ ففــي يــوم‬\n‫االثنــن ‪ 1433/10/16‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬للنظــر يف‬\n‫الدعــوى املقدمــة مــن ‪ ......‬ضــد ‪ ......‬وبالنــداء علــى الطرفــن لــم يحضــر‬\n‫منهمــا أحــد علــى الرغــم مــن انتظارهمــا إلــى ســاعة قفــل هــذه اجللســة‬\n‫الســاعة التاســعة والنصــف عليــه وبنــاء علــى املــادة الثالثــة واخلمســن مــن‬\n‫نظام املرافعات الشــرعية فقد شــطبت هذه الدعوى للمرة األولى وباهلل‬\n‫التوفيــق ويف جلســة أخــرى يف يــوم االثنــن ‪1434/04/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 9 : 00‬صباحـ ًا وفيهــا حضــر املدعــي ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه ولــم تردنــا أوراق‬\n‫التبليــغ حتــى تاريخــه وعليــه قــررت رفــع اجللســة إلعــادة تبليــغ املدعــى‬\n‫عليــه يف اجللســة القادمــة ويف يــوم الثالثــاء ‪1434/05/28‬ه ـ الســاعة‬\n                                                                                     ‫‪38‬‬\n\f     ‫التاســعة صباح ـ ًا لــدي أنــا (‪ )....‬القاضــي باحملكمــة العامــة بالطائــف‬\n     ‫القائــم بعمــل املكتــب القضائــي اخلامــس افتتحــت اجللســة وفيهــا حضــر‬\n     ‫املدعــي (‪ )....‬املثبــت هويتــه بعاليــه ولــم يحضــر املدعــى عليــه (‪ )....‬علــى‬\n     ‫الرغــم مــن تبلغــه لشــخصه مبوعــد هــذه اجللســة حســب خطــاب مديــر‬\n     ‫مركــز شــرطة الفيصليــة رقــم ‪ 1740‬يف ‪1434/5/8‬ه ـ املتضمــن أنــه مت‬\n     ‫إبــاغ املذكــور مــن قبــل العمــدة مبوعــد هــذه اجللســة لــذا واســتنادا إلــى‬\n     ‫املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد قــررت‬\n     ‫الســير يف نظــر هــذه الدعــوى غيابيــا وبســؤال املدعــي عــن دعــواه ادعــى‬\n     ‫قائــا اشــتريت مــن املدعــى عليــه الغائــب أرض يف وادي العــرج بالطائــف‬\n     ‫ا وعنــد‬   ‫مببلــغ قــدره خمســة وعشــرون ألــف ريــال اســتلمه كام ـ ً‬\n     ‫حضــوري ملعاينــة األرض واســتالمها رفــق املدعــى عليــه حضــر لنــا اثنــان‬\n     ‫مــن أبنــاء عمومتــه ونازعونــي يف األرض وذكــروا لــي أن املدعــى عليــه‬\n     ‫بــاع مــا ال ميلــك ثــم بعــد مداولــة بيننــا اســتعد املدعــى عليــه بــأن يكتــب‬\n     ‫لــي ســند باملبلــغ الــذي اســتلمه منــي مقابــل فســخ البيــع وبالفعــل قــام‬\n     ‫بتحريــر ســند باملبلــغ بتاريــخ ‪1432/6/30‬ه ـ والتــزم لــي بالســداد خــال‬\n     ‫ســنة مــن تاريــخ حتريــر الســند وقــد حــل كامــل املبلــغ ولــم يســدد لــي منــه‬\n     ‫شــيئ ًا حتــى اآلن أطلــب إلزامــه بســداده لــي حــا ًال هكــذا ادعــى وبســؤال‬\n     ‫املدعــي هــل لديــه بينــة علــى دعــواه قــال لــدي الســند املذكــور وشــاهدين‬\n     ‫علــى ذلــك ومســتعد بإحضارهمــا حــال الطلــب عليــه قــررت رفــع اجللســة‬\n     ‫وأفهمــت املدعــي بإحضــار أصل الســند املشــار إليــه يف الدعوى وإحضار‬\n     ‫الشــاهدين الذيــن ذكرهمــا ومزكــن لهمــا يف اجللســة القادمــة املقــررة‬\n     ‫يف يــوم الثالثــاء ‪1434/06/27‬ه ـ الســاعة العاشــرة صباحـ ًا ففهــم ذلــك‬\n     ‫ويف يــوم الثالثــاء ‪1434/06/27‬ه ـ الســاعة العاشــرة صباح ـ ًا افتتحــت‬\n\n\n‫‪39‬‬\n\f‫اجللســة وفيهــا حضــر املدعــي وبســؤاله عــن البينــة التــي ُطلبــت منــه يف‬\n‫اجللســة الســابقة قــال بالنســبة للســند فقــد أحضرتــه معــي وبالنســبة‬\n‫للشــهود فلــم اســتطع إحضارهــم بســبب مشــاغلهم هكــذا قــال ثــم‬\n‫أبــرز ورقــة الســند وباالطــاع عليهــا وجــدت تتضمــن مــا نصــه ( أقــر أنــا‬\n‫املدعــو ‪ ......‬حامــل بطاقــة رقــم وتاريــخ ‪1403/1/7‬ه ـ ســجل الطائــف‬\n‫بأنــي اقترضــت مبلــغ وقــدره ‪ # 25000#‬خمســة وعشــرون ألــف ريــال‬\n‫فقــط مــن املدعــو حامــل بطاقــة رقــم وتاريــخ ‪1414/3/4‬ه ـ اقترضتــه‬\n‫بتاريــخ ‪1432/6/16‬ه ـ وأتعهــد بتســديده خــال ‪ 15‬يــوم مــن تاريــخ أي‬\n‫يف ‪1432/6/30‬ه ـ بــإذن اهلل وشــهد بذلــك شــاهد أول بصمتــه شــاهد‬\n‫ثانــي بصمتــه املقــر بذلــك توقيعــه وبصمــة إبهامــه ) اه ـ ‪ .‬ثــم جــرى ســؤاله‬\n‫هــل لديــه زيــادة بينــة قــال ليــس لــدي ســوى مــا أبــرزت ثــم جــرى ســؤاله‬\n‫هــل هــو مســتعد بــأداء اليمــن طبــق دعــواه قــال نعــم ثــم بعــد اإلذن لــه‬\n‫ا واهلل العظيــم إن لــي يف ذمــة املدعــى عليــه الغائــب مبلغ ـ ًا‬ ‫حلــف قائ ـ ً‬\n‫قــدره خمســة وعشــرون ألــف ريــال قيمــة ارض اشــتريتها منــه ولــم‬\n‫يســتطع حتريرهــا لــي ثــم كتــب لــي ســند باملبلــغ التــزم بســداده لــي‬\n‫بتاريــخ ‪1432/06/30‬ه ـ ولــم يســلمني منــه شــيئ ًا هكــذا حلــف فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى ولتخلــف املدعــى عليــه عــن حضــور اجللســات‬\n‫مــع تبلغــه لشــخصه وملــا ورد يف الســند الــذي أبــرزه املدعــي وألن اليمــن‬\n‫تشــرع بجانــب أقــوى املتداعيــن ولقــوة جانــب املدعــي يف هــذه الدعــوى‬\n‫وذلــك بتخلــف املدعــى عليــه والســند الــذي أبــرزه وحللــف املدعــي اليمــن‬\n‫التــي طلبــت منــه وألنــه يســوغ القضــاء علــى الغائــب حتــى ولــو لــم تكــن‬\n‫مــع املدعــي بينــة قويــة حتــى ال يكــون التخلــف ذريعــة إلــى ضيــاع احلقــوق‬\n‫التــي ُنصــب القاضــي حلفظهــا وملــا ورد يف املــادة اخلامســة واخلمســن مــن‬\n\n\n                                                                                      ‫‪40‬‬\n\f     ‫نظــام املرافعــات الشــرعية فقــد حكمــت علــى املدعــى عليــه الغائــب‬\n     ‫بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره خمســة وعشــرون ألــف ريــال‬\n     ‫ويعــد هــذا احلكــم حضوري ـ ًا وفق ـ ًا للمــادة ‪ 1/155‬وســيتم إبــاغ‬  ‫حــا ًال ُ‬\n     ‫املدعــى عليــه بنســخة مــن احلكــم لتقــدمي مــا لديــه خــال ثالثــن يوم ـ ًا‬\n     ‫مــن تاريــخ اســتالمه لهــا وإذا مضــت املــدة ولــم يقــدم مــا لديــه فيســقط‬\n     ‫حقــه يف االعتــراض وطلــب االســتئناف ويكتســب احلكــم القطعيــة‬\n     ‫وعليــه جــرى التوقيــع وأقفلــت اجللســة الســاعة العاشــرة والنصــف وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/06/27‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم اخلميــس ‪1434/10/15‬ه ـ الســاعة‬\n     ‫العاشــرة صباح ـ ًا لــدي أنــا القاضــي باحملكمــة العامــة بالطائــف‬\n     ‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n     ‫قــرار التصديــق الصــادر مــن الدائــرة احلقوقيــة األولــى برقــم ‪34325090‬‬\n     ‫يف ‪1434/09/23‬ه ـ املتضمــن أنــه تقــررت املوافقة على احلكم والغائب‬\n     ‫علــى حجتــه عليــه أمــرت بإحلــاق ذلــك بالضبــط وســجله وعليــه جــرى‬\n     ‫التوقيــع وأقفلــت اجللســة عنــد الســاعة العاشــرة والربــع وبــاهلل التوفيــق‬\n                                                       ‫حــرر يف ‪1434/10/15‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 341210605‬وتاريــخ‬\n     ‫‪1434/9/14‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي‬\n     ‫باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪ 34253738‬وتاريــخ‬\n     ‫‪1434/6/27‬هـ ـ واملتضمــن دعــوى ‪ ....‬ضــد ‪ ......‬واحملكــوم فيــه مبــا‬\n\n\n‫‪41‬‬\n\f‫دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم والغائــب علــى حجتــه واهلل املوفــق‪ .‬وصلــى‬\n                       ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪42‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":37,"source_page_end":42,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c162c8cde5e2338c75f7d110293d3d4277a24e2b2da4374a63f4c72ac9742d78","normalized_text_hash":"071c094e99b542881c8793eca558594eac9a32053e6a4aa5b4db79e0bf70a284","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p37-34253738"},{"id":"82b2744e-a119-5885-841c-3842e205fd53","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع غير نظامي -إدعاء وجود غنب يف الثمن -املطالبة مبا زاد من قيمة عقد العقار عن قيمته األصلية -قرينه اخلبرة يف البيع والداللة ينتفى معه وجود الغن -احلكم بعدم ثبوت الدعوى وصرف النظر عنها -افهام الطرفن بأن احلكم ال يفيد التملك وإمنا هو لفض النزاع .","document_number":"33481760","case_number":"33225573","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"بيع -عقد -بيع غير نظامي -إدعاء وجود غنب يف الثمن -املطالبة مبا زاد من قيمة عقد العقار عن قيمته األصلية -قرينه اخلبرة يف البيع والداللة ينتفى معه وجود الغن -احلكم بعدم ثبوت الدعوى وصرف النظر عنها -افهام الطرفن بأن احلكم ال يفيد التملك وإمنا هو لفض النزاع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/12/28 :‬هـ‬\n                       ‫ُ‬               ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33481760:‬‬\n                         ‫َر ْق ُم الدعوى‪33225573 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34273206‬تاريخه‪1434/7/19 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬بيــع غيــر نظامــي ‪ -‬إدعــاء وجــود غنب يف الثمن ‪ -‬املطالبة‬\n      ‫مبــا زاد مــن قيمــة عقــد العقــار عــن قيمتــه األصليــة ‪ -‬قرينــه اخلبــرة يف‬\n      ‫البيــع والداللــة ينتفــى معــه وجــود الغــن ‪ -‬احلكــم بعــدم ثبــوت الدعوى‬\n      ‫وصــرف النظــر عنهــا ‪ -‬افهــام الطرفــن بــأن احلكــم ال يفيــد التملــك‬\n                                                          ‫وإمنــا هــو لفــض النــزاع ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــول البهوتــي يف كشــاف القنــاع «وأمــا مــن لــه خبــرة بســعر املبيــع‬\n      ‫ويدخــل علــى بصيــرة بالغــن ومــن غــن الســتعجاله يف البيــع ولو توقف‬\n      ‫فيــه ولــم يســتعجل لــم يغــن فــا خيــار لهمــا لعــدم التغريــر» ( ‪.) 435/7‬‬\n      ‫‪ .2‬الفقــرة الثانيــة مــن املــادة الثامنــة واخلمســن بعــد املائتــن مــن‬\n      ‫نظــام املرافعــات الشــرعية ونصهــا « إذا اســتدعى احلــال ضــرورة اإلســراع‬\n      ‫يف فصــل النــزاع يف عقــار ليــس عليــه حجــة اســتحكام فيفصــل فيــه‬\n      ‫دون اتخــاذ إجــراءات االســتحكام وينــص يف الصــك علــى أن احلكــم ال‬\n      ‫يكفــي إلثبــات التملــك وال يقــوم مقــام حجــة االســتحكام وال يســتند‬\n                                                               ‫عليــه يف أي إفــراغ»‪.‬‬\n\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه باعــه قطــع أراضــي‬\n\n‫‪43‬‬\n\f‫وألنــه غــن يف ثمنهــا فهــو يطلــب إلــزام املشــتري بــأن يدفــع لــه فــارق‬\n‫ثمــن املثــل بثمنهــا املشــترى ‪ ،‬أقــر املدعــى عليــه بشــراء القطــع املشــار‬\n‫لهــا يف الدعــوى وأنكــر الغــن وطلــب رد دعــواه ‪ ،‬ظهــر بــأن القطــع‬\n‫ال متلــك بصكــوك شــرعية مســتوفية االجــراءات وإمنــا بوثائــق عاديــة ‪،‬‬\n‫ســألت الدائــرة املدعــي عــن مجــال عملــه فقــرر بأنــه يعمــل معقبــا لــدى‬\n‫الدوائــر احلكوميــة ويعمــل يف مجــال داللــة العقــار لــدى أحــد املكاتــب‬\n‫العقاريــة ‪ ،‬عليــه وإلنــكار املدعــى عليــه الغــن وملــا قــرره الفقهــاء مــن‬\n‫حصــر خيــار الغــن يف متلقــي الركبــان والنجــش واملسترســل واألخيــر‬\n‫هــو اجلاهــل‪ ،‬وإلقــرار املدعــي بعملــه يف داللــة العقــار يف إحــدى املكاتــب‬\n‫العقاريــة وهــذه قرينــة ظاهــرة تكــذب دعــواه يف وجــود الغــن وتثبــت‬\n‫خبرتــه ممــا ينتفــى معــه وجــود الغــن يف بيعــه للعقــار املذكــور قــال يف‬\n‫كشــاف القنــاع «وأمــا مــن لــه خبــرة بســعر املبيــع ويدخــل علــى بصيــرة‬\n‫بالغــن ومــن غــن الســتعجاله يف البيــع ولــو توقــف فيــه ولــم يســتعجل‬\n‫لــم يغــن فــا خيــار لهمــا لعــدم التغريــر» ( ‪ ،) 435/7‬وجلميــع مــا تقــدم‬\n‫فقــد حكمــت الدائــرة بعــدم ثبــوت دعــوى املدعــي وصرفــت النظــر عنهــا‬\n‫‪ ،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــي عــدم قناعتــه باحلكــم‬\n‫وأفهــم بتعليمــات االســتئناف ‪ ،‬عــادت القضيــة مــن محكمة االســتئناف‬\n‫بطلــب أن ينــص يف منطــوق احلكــم بــأن الصــك ال يفيــد التملــك وال‬\n‫يســتند عليــه يف إفــراغ وإمنــا هــو لفــض النــزاع وفقــا للفقــرة الثانيــة مــن‬\n‫املــادة الثامنــة واخلمســن بعــد املائتــن مــن اللوائــح التنفيذيــة لنظــام‬\n‫املرافعــات الشــرعية اســتجابت احملكمــة للملحوظــة ‪ ،‬صــدق احلكــم‬\n                                                   ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n                                                                                       ‫‪44‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33225573‬‬\n     ‫وتاريــخ ‪1433/3/29‬ه ـ املقيــد باحملكمــة برقــم ‪ 33600786‬وتاريــخ‬\n     ‫‪1433/03/29‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪............‬ســعودي ‪،‬‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وحضــر حلضــوره املدعــى‬\n     ‫عليــه وكالــة ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .............‬الوكيــل الشــرعي عــن ‪ ..........‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪26974‬‬\n     ‫وتاريــخ ‪1433/06/21‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة وقبــول‬\n     ‫األحــكام واالعتــراض عليهــا والوكيــل أيضــا عــن ‪ .............‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة عــدل جــدة الثانيــة مبحافظــة جــدة برقــم‬\n     ‫‪65726‬وتاريــخ ‪1432/07/17‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة‬\n     ‫وقبــول األحــكام واالعتــراض عليهــا وبســؤال املدعــي عــن دعــواه أجــاب‬\n     ‫قائــا لقــد قمــت ببيــع عــدد ‪ 12‬قطعــة أرض تقــع جميعهــا يف ‪ ...‬جنــوب‬\n     ‫جــدة بقيمــة إجماليــة قدرهــا مائــة ألــف ريــال وقــد اشــتراها منــي املدعــى‬\n     ‫عليــه ‪ .........‬وقــد طلبــت منــي بعــد شــراء املدعــى عليــه لهــا بثالثــة أيــام‬\n     ‫خمــس وثالثــن ألــف ريــال لــكل قطعــة فتكــون القيمــة اإلجماليــة‬\n     ‫جلميــع القطــع مبلغــا قــدره أربعمائــة وعشــرون ألــف ريــال وقــد غبنــت‬\n     ‫وبخســت يف هــذا البيــع مــن قبــل املدعــى عليــه وقــد وقــع علــي ضــرر‬\n     ‫مــن هــذا علمــا بــأن هــذا التقديــر حصــل يف نهايــة عــام ‪1432‬ه ـ ممــا‬\n\n‫‪45‬‬\n\f‫يعنــي أن األســعار قــد ارتفعــت لــذا أطلــب احلكــم علــى املدعــى عليــه‬\n‫بــأن يدفــع لــي فــرق ســعر مــا قــدرت بــه هــذه األرض وقــدر ذلــك ثالثمائــة‬\n‫وعشــرون ألــف ريــال هــذه دعــواي وبســؤال املدعــي وهــل لهــذه األراضــي‬\n‫صكــوك شــرعية فأجــاب قائــا إن هــذه األراضــي امتلكهــا مبوجــب‬\n‫وثائــق غيــر رســمية هكــذا أجــاب وبســؤال املدعــى عليــه وكالــة عمــا‬\n‫جــاء يف دعــوى املدعــي أجــاب قائــا مــا ذكــره املدعــي يف دعــواه مــن‬\n‫قيــام موكلــي بشــراء العقــار فهــذا غيــر صحيــح فمــن اشــترى العقــار مــن‬\n‫املدعــى عليــه باملبلــغ املذكــور هــو موكلــي اآلخــر ‪ ...........‬وقــد اشــترى‬\n‫موكلــي هــذا العقــار بعــد تقييــم العقــار مــن قبــل املدعــي وبعــد أن رضــي‬\n‫بالســعر ومت البيــع ومــا ذكــره مــن وجــود الغــن فهــذا غيــر صحيــح‬\n‫هكــذا أجــاب وبســؤال املدعــي عــن عملــه أجــاب قائــا إننــي متســبب‬\n‫ال وظيفــة لــي وأعمــل يف التعقيــب لــدى اجلهــات احلكوميــة وأعمــل يف‬\n‫الداللــة علــى العقــار مــع أحــد املكاتــب العقاريــة التــي ميتلكهــا صاحــب‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬‫لــي هكــذا أجــاب فبنـ ً‬\n‫أن املدعــي يدعــي وجــود الغــن يف بيعــه للعقــار ويطالــب مبــا زاد مــن‬\n‫قيمــة العقــار عــن قيمتــه األصليــة التــي مت البيــع بهــا وحيــث أن املدعــى‬\n‫عليــه صــادق علــى البيــع بالســعر املذكــور ونفــى وجــود الغــن مــن البائــع‬\n‫وحيــث أن الفقهــاء قــد قــرروا حصــر خيــار الغــن يف متلقــي الركبــان‬\n‫والنجــش واملسترســل واألخيــر هــو اجلاهــل يف داللــة العقــار يف إحــدى‬\n‫املكاتــب العقاريــة قرينــة ظاهــرة تكــذب دعــواه يف وجــود الغــن وتثبــت‬\n‫خبرتــه ممــا ينتفــى معــه وجــود الغــن يف بيعــه للعقــار املذكــور قــال يف‬\n‫كشــاف القنــاع ( وأمــا مــن لــه خبــرة بســعر املبيــع ويدخــل علــى بصيــرة‬\n‫بالغــن ومــن غــن الســتعجاله يف البيــع ولــو توقــف ) فيــه ولــم يســتعجل‬\n\n\n                                                                                     ‫‪46‬‬\n\f     ‫لــم يغــن فــا خيــار لهمــا لعــدم التغريــر ) ( ‪ ) 435/7‬جلميــع مــا تقــدم فقــد‬\n     ‫حكمــت بعــدم ثبــوت دعــوى املدعــي وصرفــت النظــر عنهــا وبعــرض‬\n     ‫احلكــم علــى الطرفــن قــرر املدعــي عــدم قناعتــه باحلكــم وقــرر املدعــى‬\n     ‫عليــه قناعتــه باحلكــم وأفهــم املدعــي بــأن لــه ثالثــون يومــا اعتبــارا مــن‬\n     ‫تاريــخ هــذا اليــوم لتقــدمي الئحتــه االعتراضيــة خــال املــدة النظاميــة‬\n     ‫كمــا جــرى إفهامــه بأنــه يف حالــة تأخــره عن تقدمي الالئحــة االعتراضية‬\n     ‫خــال املــدة النظاميــة فــإن احلكــم يكتســب القطعيــة ويســقط حقــه يف‬\n     ‫االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/12/28‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليوم األربعاء املوافــق ‪1434/01/28‬هـ‬\n     ‫افتتحــت اجللســة بعــد ورود االســتدعاء املقــدم مــن ‪ ........‬واملقيــد يف‬\n     ‫هــذه احلكمــة برقــم ‪34213271‬وتاريــخ ‪1434/01/25‬ه ـ والــذي‬\n     ‫جــرى االطــاع عليــه فلــم يظهــر لــي منــه مــا يؤثــر علــى مــا حكمــت بــه‬\n     ‫وأمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n     ‫يف ‪1434/01/28‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء‬\n     ‫املوافــق ‪1434/07/05‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬بعــد ورود‬\n     ‫املعاملــة مــن محكمــة االســتئناف يف مكــة املكرمــة مبوجــب اخلطــاب‬\n     ‫رقــم ‪34666295‬وتاريــخ ‪1434/06/21‬ه ـ واملقيــد يف هــذه احملكمــة‬\n     ‫برقــم ‪ 34666295‬وتاريــخ ‪1434/06/26‬ه ـ واملتضمــن القــرار الصــادر‬\n     ‫مــن أصحــاب الفضيلــة قضــاة محكمــة االســتئناف أعضــاء الدائــرة‬\n     ‫احلقوقيــة األولــى ذي الرقــم ‪ 34243738‬وتاريــخ ‪1434/06/18‬ه ـ‬\n     ‫واملتضمــن مــا يلــي ( وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n\n\n‫‪47‬‬\n\f‫االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا لتضمــن حكمــه باملــادة‬\n‫‪ 2/258‬مــن نظــام املرافعــات والتمشــي بهــا واهلل املوفــق ) اه ـ ‪ .‬ولوجاهــة‬\n‫مــا ذكــره أصحــاب الفضيلــة وفقهــم اهلل فقــد تقرر تضمني ما حكمت‬\n‫بــه أعــاه الالئحــة التنفيذيــة الثانيــة مــن املــادة الثامنــة واخلمســن بعــد‬\n‫املائتــن مــن نظــام املرافعــات الشــرعية ونصهــا ( إذا اســتدعى احلــال‬\n‫ضــرورة اإلســراع يف فصــل النــزاع يف عقــار ليــس عليــه حجــة اســتحكام‬\n‫يف فصــل فيــه دون اتخــاذ إجــراءات االســتحكام وينــص يف الصــك علــى‬\n‫أن احلكــم ال يكفــي إلثبــات التملــك وال يقــوم مقــام حجــة االســتحكام‬\n‫وال يســتند عليــه يف أي إفــراغ ) عليــه فقــد أمــرت بإحلــاق ذلــك بصــك‬\n‫احلكــم وســجله ورفعــه إلــى محكمــة االســتئناف وبــاهلل التوفيــق‬\n‫وأقفلــت اجللســة الســاعة ‪ 11 : 35‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                    ‫نبينــا محمــد حــرر يف ‪1434/07/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 34/666295‬وتاريــخ‬\n‫‪1434/07/25‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪34/666295‬وتاريــخ‬\n‫‪1434/07/29‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪34273206‬وتاريــخ ‪1434/07/19‬ه ـ‬\n‫املتضمــن مــا نصــه‪ :‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر وبــاهلل التوفيــق ‪ .‬اه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع ‪........‬‬\n‫وقاضــي اســتئناف ختــم وتوقيــع ‪ ..........‬ورئيــس الدائــرة ختــم وتوقيــع ولــه‬\n‫وجهــة نظــر ‪ ، ..........‬عليــه فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله‬\n\n\n                                                                                      ‫‪48‬‬\n\f     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1434/8/1‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪34/666295‬‬\n     ‫وتاريخ‪1434/7/11‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n     ‫‪ .......‬القاضــي باحملكمــة العامــة مبحافظــة جــدة واملســجل بعــدد‬\n     ‫‪33481760‬وتاريــخ ‪1433/12/28‬هـ ـ واملتضمــن دعــوى ‪ ........‬ضــد ‪.......‬‬\n     ‫وكالــة عــن ‪ ........‬والوكيــل أيضــا عــن ‪ ........‬واحملكــوم فيــه مبــا دون‬\n                                                                              ‫باطنــه‪.‬‬\n     ‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n     ‫باألكثريــة املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق‪.‬‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪49‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":43,"source_page_end":49,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"16020bfaa7e27a79e4c3ca9e67e42bd07c70914c0cf6f76eb023d375317878b9","normalized_text_hash":"5b96a765506988b80343742a43a3d8ddf98f91fd72c118fdac3eb777c3680a9a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p43-33481760"},{"id":"e11d3a6f-bf9b-5bc9-8db7-2686ff099045","document_type":"judgment","category":"judicial","subcategory":"general","title":"بي ع -بي ع لف ات أس اك كهربائية دون قب ض الثم ن -املطالبة بثمن األس اك الكهربائية -إنك ار املدعى عليه وك الة -بينة املدعي شاهد وعقد مين -احلكم بدفع الثمن .","document_number":"34264475","case_number":"33231447","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/10","year":"1434","subject":"بي ع -بي ع لف ات أس اك كهربائية دون قب ض الثم ن -املطالبة بثمن األس اك الكهربائية -إنك ار املدعى عليه وك الة -بينة املدعي شاهد وعقد مين -احلكم بدفع الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34264475 :‬‬\n                   ‫َر ْق ُم الدعوى‪33231447 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34382735‬تاريخه‪1434/12/19 :‬هـ‬\n\n\n‫بيـ ــع ‪ -‬بي ــع لـف ــات أس ــاك كهربائيــة دون قب ــض الثم ــن ‪ -‬املطالبــة‬\n‫بثمــن األس ــاك الكهربائيــة ‪ -‬إنكـ ــار املدعــى عليــه وك ــالة ‪ -‬بينــة‬\n                  ‫املدعــي شــاهد وعقــد ميــن ‪ -‬احلكــم بدفــع الثمــن ‪.‬‬\n\n\n\n                     ‫‪ -1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود) ‪.‬‬\n         ‫‪ -2‬حديث (املسلمون على شروطهم) رواه الترمـذي وأبو داوود‪.‬‬\n‫‪ -3‬احلديــث املــروي عــن ابــن عبــاس ‪ :‬أن الرس ــول صلــى اهلل عليــه وســلم‬\n                         ‫قضــى باليمــن مــع الشاه ـ ــد ‪ .‬رواه أحم ــد وغيــره ‪.‬‬\n‫‪ -4‬وملــا قــرره الفقهــاء مــن قبــول شــهادة الشــاهد الواحــد مــع ميــن‬\n‫املدعــي يف املــال ومــا يقصــد بــه املــال ‪ ،‬ومــن ذلــك مــا ذكــره صاحــب‬\n‫الــروض املربــع ونصــه ‪( :‬ويقبــل يف املــال ومــا يقصــد بــه املــال كالبيــع‬\n‫واألجــل واخليــار فيــه أي يف البيــع ونحــوه ‪ ..‬رجــل‪ .‬وميــن املدعــي) ‪.‬‬\n‫‪ -5‬حديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) رواه‬\n‫الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عليــه عنــد أهــل العلــم مــن أصحــاب‬\n                                              ‫النبــي صلــى اهلل عليــه وســلم ‪.‬‬\n\n\n\n‫دعــوى املدعــي يف كــون املدعــى عليــه اشــترى منــه عــدد ألفــي لفــة‬\n‫ســلك كهربائــي بثمــن إجمالــي قــدره ســبعمائة وخمســون ألــف ريــال‬\n\n                                                                                    ‫‪50‬‬\n\f     ‫مؤجل‪،‬اســتلم املدعــى عليــه البضاعــة مــن احملــل وتصــرف فيهــا ‪ -‬حــل‬\n     ‫األجل‪،‬ولــم يســدد املدعــى عليــه مــن املبلــغ شــيئا‪ ،‬طلــب إلــزام املدعــى‬\n     ‫عليــه بســداد املبلــغ وقــدره ســبعمائة وخمســون ألــف ريــال‪ ،‬حضــر‬\n     ‫املدعــى عليــه وكالــة وأنكــر مــا جــاء يف الدعــوى‪ ،‬جــرى االســتخالف‬\n     ‫لســماع شــهادة الشــاهد وتزكيتــه وأبــرز املدعــي العقــد وجــرى حتليفــه‬\n     ‫اليمــن‪ ،‬ملــا ذكــره القاضــي مــن حيثيــات ولقولــه تعالــى (يــا أيهــا الذيــن‬\n     ‫آمنــوا أوفــوا بالعقــود) وقولــه صلــى اهلل عليــه وســلم‪( :‬املســلمون علــى‬\n     ‫شــروطهم) ولقضائــه صلــى اهلل عليــه وســلم بالشــاهد واليمــن لــذا صدر‬\n     ‫احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه للمدعــي ‪ ،‬اعتــرض‬\n     ‫املدعــى عليــه علــى احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33231447‬وتاريــخ‬\n     ‫‪1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33598853‬وتاريــخ‬\n     ‫‪1433/03/29‬ه ـ ففــي يــوم الســبت املوافق‪1433/09/09‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 01 :00‬وفيهــا حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ ...........‬بصفتــه وكيــا عــن املدعــي ‪ ..........‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل وادي الدواســر برقــم ‪ 1/3129‬وتاريــخ ‪1433/7/7‬ه ـ‬\n     ‫جلــد ‪ 1/4935‬ولــم يحضــر املدعــى عليــه ‪ ............‬وال مــن ميثلــه ‪ ،‬وقــد‬\n\n‫‪51‬‬\n\f‫وردنــا خطــاب محافــظ جــدة برقــم ‪933292‬ج‪/‬أ وتاريــخ ‪1433/7/29‬ه ـ‬\n‫املتضمــن تبليــغ املدعــى عليــه باحلضــور أو إرســال وكيــل شــرعي لــه‬\n‫يــوم الســبت املوافــق ‪1433/9/9‬ه ـ الســاعة ‪ . 01 : 00‬أه ـ فبنــاء علــى‬\n‫املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت النظــر يف الدعــوى‬\n‫غيابيــا يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي وكالــة قائــا ‪ :‬لقــد‬\n‫اشــترى املدعــى عليــه مــن موكلــي عــدد ألفــي لفــة ســلك كهربائــي‬\n‫مقــاس أربعــة مليمتــر وبطــول خمســمائة قــدم ‪ ،‬بســعر اللفــة الواحــدة‬\n‫مبلغــا قــدره ثالثمائــة وخمســة وســبعون ريــال ‪ ،‬وبثمــن إجمالــي قــدره‬\n‫ســبعمائة وخمســون ألــف ريــال يف ‪1429/6/2‬ه ـ مؤجلــة ألجــل يحــل‬\n‫يف ‪1429/12/2‬ه ـ ‪ ،‬وقــد اســتلم املدعــى عليــه البضاعــة مــن محــل‬\n‫‪ .................‬وتصرف فيها ‪ ،‬مبوجب عقد مبايعة مؤرخ يف ‪1429/6/2‬هـ‬\n‫علــى أوراق مكتــب ‪ ، ...........‬وموقعــة مــن قبــل املدعــى عليــه وموكلــي‬\n‫وشــاهدين همــا ‪ .........‬و‪ ، ...............‬ولــم يســدد املدعــى عليــه موكلــي‬\n‫مــن ذلــك املبلــغ شــيئا حتــى اآلن ‪ ،‬أطلــب إلزامــه بدفــع املبلــغ املدعــى‬\n‫بــه وقــدره ســبعمائة وخمســون ألــف ريــال ‪ .‬هــذه دعــواي ‪ .‬وبســؤال‬\n‫املدعــي وكالــة البينــة علــى دعــواه أبــرز أصــل عقــد املبايعــة املشــار إليــه‬\n‫‪ ،‬وقــال ‪ :‬أطلــب اســتخالف محكمــة وادي الدواســر لســماع شــهادة‬\n‫الشــاهدين وغيرهمــا ممــن يشــهد بذلــك ‪ .‬ثــم رفعــت اجللســة للكتابــة‬\n‫لرئيــس محكمــة وادي الدواســر الســتخالفه أو مــن ينيبــه مــن أصحــاب‬\n‫الفضيلــة يف ســماع شــهادة الشــهود يف دعــوى املدعــي ‪ .‬ويف يــوم األحــد‬\n‫املوافــق ‪1434/01/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 00‬وفيهــا‬\n‫حضــر املدعــي وكالــة ‪ ،‬وحضــر ‪ ............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ............‬بصفتــه وكيــا عــن املدعــى عليــه ‪............‬‬\n\n\n                                                                                        ‫‪52‬‬\n\f     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل وادي الدواســر برقــم ‪ 1/4308‬وتاريــخ‬\n     ‫‪1433/11/22‬ه ـ جلــد ‪ ، 1/4993‬وبعــرض دعــوى املدعــي علــى املدعــى‬\n     ‫عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد بعــد الرجــوع ملوكلــي حيــث‬\n     ‫أن موكلــي مســافر وال أعلــم متــى ســيعود ‪ .‬وقــد وردنــا خطــاب رئيــس‬\n     ‫احملكمــة العامــة بــوادي الدواســر رقــم ‪1/5768/4/1436‬وتاريــخ‬\n     ‫‪1433/11/20‬ه ـ بشــأن االســتخالف لهــم واملتضمــن أنــه مت إجــراء‬\n     ‫الــازم ‪ .‬أه ـ وبالرجــوع خلطابــه اتضــح وجــود مرفــق هــو صــورة مــن ضبــط‬\n     ‫تتضمــن أنــه حضــر ‪( ...........‬وأبــرز بطاقتــه الوطنيــة وســجله املدنــي‬\n     ‫‪ ...........‬وهــو مــن مواليــد وادي الدواســر بتاريــخ ‪1357/7/1‬ه ـ وقــال‬\n     ‫‪ .........‬أنــا الــذي كتبــت بــن ‪ .........‬و‪ ...........‬وأشــهد بــاهلل العظيــم بأنــه‬\n     ‫يف تاريــخ ‪1429/6/2‬ه ـ حضــرت مجلــس كان فيــه رجــال مــن ضمنهــم‬\n     ‫‪ .........‬و‪ ..........‬وقــد كانــت هنــاك ديانــة بينهمــا وأشــهد بــاهلل العظيــم‬\n     ‫بــأن ‪ ...........‬قــد بــاع ‪ .........‬ألفــي لفــة ســلك كهربــاء مقــاس ‪ 4‬مــل بطــول‬\n     ‫خمســمائة قــدم ســعر اللفــة الواحــدة ثالثمائــة وخمســة وســبعني ريــال‬\n     ‫وإجمالــي املبلــغ هــو مبلــغ قــدره ســبعمائة وخمســون ألــف ريــال مؤجلــة‬\n     ‫إلــى ســتة أشــهر أي أن تاريــخ حلــول التســليم للقيمــة ‪1429/12/2‬ه ـ‬\n     ‫وقــد حــول ‪ .......‬املشــتري ‪ ........‬إلــى محــل ‪ .........‬وأشــهد بــاهلل العظيــم‬\n     ‫بأننــي ملــا ســألت ‪ ............‬عــن االســتالم قــال نعــم اســتلمتها وتصرفــت‬\n     ‫فيهــا هــذا مــا لــدي وبــه أشــهد شــهادة هلل هــذا مــا لــدي) ‪ .‬وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال أيضــا للــرد ‪ .‬ثــم جــرى‬\n     ‫اطــاع املدعــى عليــه وكالــة علــى أصــل عقــد املبايعــة ‪ ،‬ومت تزويــده‬\n     ‫بنســخة منهــا للــرد عليهــا يف اجللســة القادمــة ‪ .‬ثــم رفعــت اجللســة لذلــك ‪.‬‬\n\n\n‫‪53‬‬\n\f‫ويف يــوم الســبت املوافــق ‪1434/05/18‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 09 :‬وفيهــا حضــر املدعــي وكالــة ‪ ...........‬كمــا حضــر ‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬بصفتــه وكيــا عــن املدعــي‬\n‫عليــه ‪ ...............‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل محافظــة‬\n‫وادي الدواســر برقــم ‪ 2/129‬يف ‪1422/01/17‬ه ـ جلــد ‪، 319‬‬\n‫وبســؤال املدعــى عليــه وكالــة عمــا طلــب الوكيــل الســابق اإلمهــال مــن‬\n‫أجلــه قــال ‪ :‬إنــه ال علــم لــي بالدعــوى ‪ ،‬وقــد طلــب منــي احلضــور فقــط‬\n‫‪ ،‬وتأجيــل اجللســة جللســة أخــرى وتبليغهــم بذلــك ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــي وكالــة قــال ‪ :‬هــذا تطويــل ألمــد التقاضــي ‪ ،‬وأطلــب احلكــم‬\n‫ملوكلــي يف الدعــوى ‪ .‬ثــم طلبــت مــن املدعــي وكالــة تعديــل الشــاهد‬\n‫وإحضــار املدعــي أصالــة ألداء اليمــن علــى صحة الدعوى وعدم اســتالم‬\n‫املدعــي لشــيء مــن مبلــغ الدعــوى فقــال ‪ :‬أطلــب اســتخالف احملكمــة‬\n‫العامــة مبحافظــة وادي الدواســر حيــث أن معدلــي الشــاهد وموكلــي‬\n‫يســكنون محافظــة وادي الدواســر ‪ ،‬ويشــق عليهــم احلضــور جلــدة ‪.‬‬\n‫ثــم رفعــت اجللســة للكتابــة لرئيــس احملكمــة العامــة مبحافظــة وادي‬\n‫الدواســر الســتخالفه أو مــن ينيبــه مــن أصحــاب الفضيلــة يف ســماع‬\n‫تعديــل الشــاهد ‪ ، ..................‬وســماع ميــن املدعــي أصالــة ‪...................‬‬\n‫علــى صحــة دعــواه وعــدم اســتالمه شــيئا مــن مبلــغ الدعــوى ‪ .‬ويف يــوم‬\n‫االثنــن املوافق‪1434/07/10‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 30‬‬\n‫وفيهــا حضــر املدعــي أصالــة ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .......‬وحضــر املدعــي وكالــة ‪ ........‬وحضــر املدعــى عليــه‬\n‫وكالــة ‪ ، .........‬وبســؤال املدعــى عليــه وكالــة عمــا طلــب اإلمهــال مــن‬\n‫أجلــه قــال ‪ :‬ال صحــة ملــا ادعــى بــه املدعــى جملــة وتفصيــا حيــث أننــي‬\n\n\n                                                                                           ‫‪54‬‬\n\f     ‫قمــت بالرجــوع إلــى موكلــي وســألته عــن تلــك الدعــوى أجــاب بــأن هــذا‬\n     ‫لــم يحــدث مطلقــا واملعــروف لــدى فضيلتكــم أن هــذه الدعــوى مرفوعــة‬\n     ‫علــى موكلــي بأنــه قــد اســتلم أســاك كهربائيــة مببلــغ ســبعمائة‬\n     ‫وخمســون ألــف ريــال وهــذا االســتالم يســتوجب معــه ذهــاب موكلــي‬\n     ‫إلــى محــل املدعــى واســتالمه األســاك والتوقيــع علــى االســتالم‬\n     ‫بنفســه وهــذا لــم يحــدث مطلقــا فموكلــي لــم يذهــب حملــات لشــراء‬\n     ‫مســتلزماته مــن احملــل مباشــر بــل هنــاك عمــال هــم املكلفــن بذلــك‬\n     ‫و أن موكلــي لــم يوقــع علــى أي عقــود مــع املدعــي وأن ادعــاؤه ادعــاء‬\n     ‫باطــل وال أســاس لــه مــن الصحــة بــل إن املدعــي يحــاول أن يثبــت حقــا‬\n     ‫علــى موكلــي ليــس إال وهــذا ال يجــوز شــرعا وأن الشــاهد الــذي شــهد‬\n     ‫باســتالم موكلــي لألســاك الكهربائيــة مطعــون يف شــهادته ألن هــذا‬\n     ‫غيــر معقــول قــوال واحــدا ألن موكلــي لــم يســتلم تلــك األســاك املدعــى‬\n     ‫بهــا جملـ ًة وتفصيــا ‪.‬وأن موكلــي لديــه مــا يثبــت أن هــذه االدعــاء باطــل‬\n     ‫مبوجــب األدلــة القاطعــة ولكــن نظــرا لســفره إلــى اخلــارج لــم اســتطيع‬\n     ‫احلصــول علــى تلــك املســتندات أطلــب مهلــه حلــن رجــوع موكلــي مــن‬\n                                                                    ‫ســفره لتقدميهــا ‪.‬‬\n     ‫وبنــاء علــى مــا ســبق التمــس مــن فضيلتكــم أصليــا رفــض الدعــوى لعــدم‬\n     ‫صحتهــا جملـ ًة وتفصيــا أو التأجيــل جللســة أخــرى إلحضــار البينــة التــي‬\n                             ‫تؤكــد عــدم صحــة دعــوى املدعــى جملـ ًة وتفصيــا ‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــي قــال ‪ :‬بــل الصحيــح مــا ذكــر يف دعــواي‬\n     ‫‪ ،‬ومقصــود املدعــى عليــه مــن ذلــك املماطلــة وتطويــل أمــد التقاضــي ‪،‬‬\n     ‫وأطلــب الفصــل يف الدعــوى ‪ .‬وبســؤال املدعــى عليــه وكالــة عــن تلــك‬\n     ‫األدلــة القاطعــة علــى بطــان دعــوى املدعــي والتــي أشــار إليهــا يف جوابــه‬\n\n\n‫‪55‬‬\n\f‫قــال ‪ :‬ال أعلــم عنهــا شــيئا ‪ .‬وبعــرض اليمــن علــى املدعــي علــى صحــة‬\n‫دعــواه ‪ ،‬وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا اســتعد لذلــك ‪ ،‬ثــم‬\n‫حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن املدعى عليه ‪..............‬‬\n‫قــد اشــترى منــي عــدد ألفــي لفــة ســلك كهربائــي مقــاس أربعــة مليمتــر‬\n‫وبطــول خمســمائة قــدم ‪ ،‬بســعر اللفــة الواحــدة مبلغــا قــدره ثالثمائــة‬\n‫وخمســة وســبعون ريــال ‪ ،‬وبثمــن إجمالــي قــدره ســبعمائة وخمســون‬\n‫ألــف ريــال يف ‪1429/6/2‬ه ـ مؤجلــة ألجــل يحــل يف ‪1429/12/2‬ه ـ ‪،‬‬\n‫وقــد اســتلم املدعــى عليــه البضاعــة مــن محــل ‪ ..............‬وتصــرف فيهــا ‪،‬‬\n‫مبوجــب عقــد مبايعــة مؤرخ يف ‪1429/6/2‬ه ـ على أوراق مكتب‪...........‬‬\n‫‪ ،‬وموقعــة مــن قبلــي واملدعــى عليــه وشــاهدين همــا ‪.................‬‬\n‫و‪ ، ................‬ولــم يســدد املدعــى عليــه لــي مــن ذلــك املبلــغ شــيئا حتــى‬\n‫اآلن ‪ .‬هكــذا حلــف ‪ .‬وبســؤال املدعــي معدلــي الشــاهد ‪ .........‬قــال ‪:‬‬\n‫لقــد مت اســتخالف محكمــة محافظــة وادي الدواســر لذلــك فوردكــم‬\n‫خطاب رئيسها بالنيابة برقم ‪ 341316806‬يف ‪1434/6/5‬هـ واملتضمن‬\n‫أنــه جــرى تعديــل الشــاهد ‪ ،‬وأمــا ســماع ميــن املدعــي أصالــة فلــم يتــم‬\n‫لعــدم إرفــاق الدعــوى املــراد أخــذ ميينــه عليهــا وأنــه لــم يتــم بيــان املبلــغ‬\n‫الــذي يتــم أخــذ ميينــه يف عــدم اســتالمه لشــيء منــه ‪ ،‬وقــد أعيــد اخلطــاب‬\n‫مبلحقاتــه مبوجــب خطــاب صــادر منكــم برقــم ‪ 341316806‬وتاريــخ‬\n            ‫‪1434/6/12‬ه ـ للمحكمــة العامــة مبحافظــة وادي الدواســر ‪.‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى إنــكار املدعــى‬\n‫عليــه وكالــة لدعــوى املدعــي ‪ ،‬وبنــاء علــى عقــد املبايعــة واملــؤرخ يف‬\n‫‪1429/6/2‬ه ـ علــى أوراق‪ ،‬وبنــاء علــى شــهادة الشــاهد ‪ ،‬وبناء على ميني‬\n‫املدعــي علــى صحــة الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا ‪،‬‬\n\n\n                                                                                           ‫‪56‬‬\n\f     ‫وحيــث اتضــح ورود خطــاب رئيــس احملكمــة العامــة مبحافظــة وادي‬\n     ‫الدواســر بالنيابــة برقــم ‪ 341316806‬يف ‪1434/6/5‬ه ـ مــن خــال مــا‬\n     ‫ورد يف خطابنــا رقــم ‪ 341316806‬وتاريــخ ‪1434/6/12‬ه ـ (واملتضمــن‬\n     ‫أنــه جــرى تعديــل الشــاهد ‪ ،‬وأمــا ســماع ميــن املدعــي أصالــة فلــم يتــم‬\n     ‫لعــدم إرفــاق الدعــوى املــراد أخــذ ميينــه عليهــا وأنــه لــم يتــم بيــان املبلــغ‬\n     ‫الــذي يتــم أخــذ ميينــه يف عــدم اســتالمه لشــيء منــه) ‪ ،‬وحيــث أن تعديــل‬\n     ‫الشــهود لــم يــرد اشــتراطه يف أدلــة الشــرع ‪ ،‬وإمنــا هــو مــن قبيــل مــا جــرت‬\n     ‫بــه العــادة والعــرف القضائــي يف الزمــن املتأخــر ‪ ،‬ولقولــه تعالــى (يــا أيهــا‬\n     ‫الذيــن آمنــوا أوفــوا بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه‬\n     ‫الترمــذي وأبــو داوود ‪ ،‬وللحديــث املــروي عــن ابــن عبــاس ‪ :‬أن الرســول‬\n     ‫صلــى اهلل عليــه وســلم قضــى باليمــن مــع الشــاهد ‪ .‬رواه أحمــد وغيــره‬\n     ‫‪ ،‬وملــا قــرره الفقهــاء مــن قبــول شــهادة الشــاهد الواحــد مــع ميــن املدعــي‬\n     ‫يف املــال ومــا يقصــد بــه املــال ‪ ،‬ومــن ذلــك مــا ذكــره صاحــب الــروض‬\n     ‫املربــع ونصــه ‪( :‬ويقبــل يف املــال ومــا يقصــد بــه املــال كالبيــع واألجــل‬\n     ‫واخليــار فيــه أي يف البيــع ونحــوه ‪ ..‬رجــل وميــن املدعــي) وحلديــث (البينــة‬\n     ‫علــى املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو‬\n     ‫عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n     ‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪،‬‬\n     ‫لذلــك كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه ‪ ........‬بدفــع مبلــغ قــدره‬\n     ‫ســبعمائة وخمســون ألــف ريــال للمدعــي ‪ ..........‬وبــه قنــع املدعــي وقــرر‬\n     ‫املدعــى عليــه وكالــة االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم‬\n     ‫وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال‬\n     ‫ســقط حقــه يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت‬\n\n\n‫‪57‬‬\n\f‫اجللســة الســاعة ‪ . 10 : 10‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة ففــي يــوم االثنــن املوافــق‪ 1435/01/08‬ه ـ افتتحــت‬\n‫اجللسة الساعة ‪ 9 : 45‬وفيها قد عادت املعاملة من محكمة االستئناف‬\n‫بخطــاب رئيســها رقــم ‪ 33598853‬وتاريــخ ‪1433/12/26‬ه ـ ومرفــق‬\n‫بهــا القــرار رقــم ‪ 34382735‬وتاريــخ ‪1434/12/19‬ه ـ ومضمونــه مــا‬\n‫يلــي ( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم وعلــى فضيلــة حاكمــه مراعــات التنبيــه ‪ .‬وأقفلــت‬\n‫اجللســة الســاعة ‪ 9 : 55‬وحتــى ال يخفــى جــرى إثباتــه ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                            ‫‪ 1435/01/08‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ .............‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n‫‪ 34264475‬وتاريــخ ‪1434/7/10‬ه ـ املتضمــن دعــوى ‪ ...........‬ضــد‬\n                                ‫‪ . ..........‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم وعلــى فضيلــة حاكمــه مراعــات التنبيــه املرفــق‬\n‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":50,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7e615a9a95acf943a5c73d225a8eda57f62e6af6bf1b2d5bd4377059bb5a035c","normalized_text_hash":"c8165edebac876310f2144fc2ac759a6a92b652ff72998473f4150876cd8ad72","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p50-34264475"},{"id":"b43d13e9-fcf4-5fff-bb30-567ea5303c1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -إثبات بيع -بيع نصيب وارث -إقرار بالبيع واستالم الثمن -رجوع عن اإلقرار -ال يصح الرجوع عن اإلقرار بحق آدمي -وجوب الوفاء بالعقود -ثبوت احلق باإلقرار والشهود العدول- احلكم بثبوت صحة بيع نصيب وارث من عقار -التهميش على صك امللكية بانتقال نصيب وارث بعد اكتساب احلكم القطعية .","document_number":"3414136","case_number":"33330846","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":"الدائرة احلقوقية األولى رقم 34169561يف 1434/3/23ه املتضمن","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"بيع -عقار -إثبات بيع -بيع نصيب وارث -إقرار بالبيع واستالم الثمن -رجوع عن اإلقرار -ال يصح الرجوع عن اإلقرار بحق آدمي -وجوب الوفاء بالعقود -ثبوت احلق باإلقرار والشهود العدول- احلكم بثبوت صحة بيع نصيب وارث من عقار -التهميش على صك امللكية بانتقال نصيب وارث بعد اكتساب احلكم القطعية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/1/17 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪3414136 :‬‬\n                       ‫َر ْق ُم الدعوى‪33330846 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34169561‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬عقــار ‪ -‬إثبــات بيــع ‪ -‬بيــع نصيــب وارث ‪ -‬إقــرار بالبيــع واســتالم‬\n     ‫الثمــن ‪ -‬رجــوع عــن اإلقــرار ‪ -‬ال يصــح الرجــوع عــن اإلقــرار بحــق آدمــي‬\n     ‫‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬ثبــوت احلــق باإلقــرار والشــهود العــدول‪-‬‬\n     ‫احلكــم بثبــوت صحــة بيــع نصيــب وارث مــن عقــار ‪ -‬التهميــش علــى‬\n     ‫صــك امللكيــة بانتقــال نصيــب وارث بعــد اكتســاب احلكــم القطعيــة ‪.‬‬\n\n\n\n                              ‫آم ُنو ْا َأوْفُ و ْا ِبا ْل ُع ُقو ِد ) ‪.‬‬ ‫‪ .1‬قوله تعالى ( َيا َأ ُّي َها ا َّلذِ َ‬\n                                                                      ‫ين َ‬\n                                                      ‫‪ .2‬اإلقرار حجة قاصرة وال عذر ملن أقر ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــي وكالــة ضــد املدعــى عليــه أن موكلــه قــد اشــترى‬\n     ‫نصيــب املدعــى عليــه مــن العقــار والــذي آل إليــه بــاإلرث مببلــغ قــدره‬\n     ‫ســبعة وعشــرون ألــف ريــال ‪ ،‬بــن صفــة وموقــع العقــار يف نــص القضيــة‬\n     ‫‪ ،‬طلــب إفــراغ نصيــب املدعــى عليــه للمدعــي أصالــة ‪ ،‬أجــاب املدعــى‬\n     ‫عليــه باإلنــكار ‪ ،‬مت اطــاع حاكــم القضيــة علــى صــك العقــار وحصــر‬\n     ‫ورثــة املدعــى عليــه ‪ ،‬أحضــر املدعــي بينــة موصلــة علــى صحــة دعــواه‬\n     ‫وهــي إقــرار خطــي منســوب للمدعــى عليــه وشــهود جــرى تعديلهم شــرع ًا‬\n     ‫ـاء علــى األســباب املرصــودة ولقولــه‬\n                                         ‫‪ ،‬رجــع املدعــى عليــه عــن إقــراره ‪ ،‬بنـ ً‬\n                                                 ‫ـوا َأ ْو ُفـ ْ‬\n     ‫ـوا ِبا ْل ُع ُقــود) صــدر احلكــم بثبــوت صحة‬         ‫آم ُنـ ْ‬\n                                                                   ‫تعالــى ( َيــا َأ ُّي َهــا ا َلّذِ يـ َـن َ‬\n‫‪59‬‬\n\f‫البيــع والتهميــش علــى صــك امللكيــة مبوجبــه بعــد اكتســاب احلكــم‬\n‫القطعيــة ‪ ،‬قــرر املدعــى عليــه عــدم القناعــة ‪ ،‬صــدر قــرار محكمــة‬\n              ‫االســتئناف باملنطقــة الشــرقية باملوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة برقــم ‪ 33330846‬يف ‪ 1433/5/12‬ه ـ يف يــوم األحــد‬\n‫املوافق‪1433/6/8‬ه ـ افتتحــت اجللســة اخلاصــة بدعــوى (‪ )....‬ضــد(‪)....‬‬\n‫وفيهــا حضــر (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم حــال‬\n‫وكالتــه عــن (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل محافظــة القطيــف برقــم‬\n‫‪ ........‬يف ‪1433/2/17‬ه ـ والتــي تخولــه حــق املرافعــة واملدافعــة‬\n‫واملخاصمــة وحضــور اجللســات وإقامــة وســماع الدعــاوى والصلــح‬\n‫والتســوية واالقــرار واالنــكار واجلــرح والتعديــل وتقــدمي البينــات وســماع‬\n‫الشــهود واســتجوابهم والطعــن فيهــم واالجابــة وطلــب حتليــف اليمــن‬\n‫واملطالبــة بكافــة احلقــوق لــدى الغيــر واســتالمها نقــد ًا وللوكيــل احلــق‬\n‫يف اســتئناف االحــكام ومتييزهــا والقناعــة بهــا واالعتــراض عليهــا‬\n‫والتظلــم وتعيــن اخلبــراء والطعــن فيهــم ويف تقاريرهــم وطلــب التحكيــم‬\n‫لــدى أي جهــة كانــت وطلــب منــع املعارضــة ورفــع اليــد وإخــاء الســبيل‬\n‫وطلــب احلجــز بجميــع أنواعــه وفكــه وتقــدمي اللوائــح التنفيذيــة لنظــام‬\n‫املرافعــات الشــرعية مبــا فيهــا املــادة رقــم ‪ 230‬والتوقيــع علــى كل مــا‬\n‫يلزم ‪ .‬أ هـ‪ .‬وحضر حلضوره ‪ .....‬ســعودي اجلنســية مبوجب الســجل املدني‬\n                                                                                   ‫‪60‬‬\n\f     ‫ا يف دعــواه‪ :‬إن موكلــي قــد اشــترى‬      ‫رقــم وادعــى املدعــي وكالــة قائ ـ ً‬\n     ‫مــن املدعــى عليــه نصيبــه مــن املزرعــة التــي آلــت إليهــم بــاإلرث مــن‬\n     ‫مورثهــم الواقعــة يف ‪........‬مبحافظــة القطيــف بثمن قدره ســبعة وعشــرون‬\n     ‫ألــف ريــال (‪ )27000‬وذلــك يف شــهر صفــر عــام ‪1420‬ه ـ لــذا أطلــب‬\n     ‫ســؤاله عــن هــذه الدعــوى واحلكــم عليــه بإفــراغ نصيبــه الــذي اشــتراه‬\n     ‫موكلــي منــه لــه هــذه دعــواي وبعــرض دعــوى املدعــي وكالــة علــى‬\n     ‫املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه غيــر‬\n     ‫صحيــح ولــم أبــع عليــه نصيبــي مــن هــذا النخــل ولســت مســتعد ًا مبــا‬\n     ‫طلــب هكــذا أجــاب وبعــرض جوابــه علــى املدعــي وكالــة أجــاب قائـاً‪:‬‬\n     ‫الصحيــح مــا ذكــرت ثــم طلبــت مــن املدعــي وكالــة صــك حصــر ورثــة‬\n     ‫وصــك العقــار محــل الدعــوى فاســتعد بإحضارهمــا يف اجللســة القادمــة‬\n     ‫ورفعــت اجللســة مــن أجــل إحضــار صــك حصــر الورثــة وصــك العقــار ويف‬\n     ‫جلســة أخــرى حضــر الطرفــان ثــم طلبــت مــن املدعــي وكالــة صــك‬\n     ‫العقــار محــل الدعــوى فأبــرزه وباالطــاع عليــه وجــد أنــه صــادر مــن هــذه‬\n     ‫احملكمــة برقــم ‪/6/3‬ح يف ‪1428/2/20‬ه ـ ويتضمــن متلــك ورثــة لثالثة‬\n     ‫أربــاع األرض والتــي حدودهــا وأطوالهــا ومســاحتها كمــا يلــي شــما ًال ‪:‬‬\n     ‫يبــدأ مــن الشــرق للغــرب بطــوال ثالثــة أمتــار وتســعني ســنتم ثــم ينكســر‬\n     ‫للشــمال بطــول ســبعة أمتــار وعشــرة ســنتم ويحــده محــول كهربــاء ثــم‬\n     ‫ينكســر احلــد للغــرب باجتــاه الشــمال الغربــي بطــول خمســة وثالثــن‬\n     ‫متــر ًا وخمســة وثمانــن ســنتم ثــم يســتمر بنفــس االجتــاه بطــول اثنــن‬\n     ‫وثالثــن متــر ًا وثمانيــة وســتني ثــم يســتمر بنفــس االجتــاه حتــى نهايــة احلــد‬\n     ‫بطــول أربعــة وعشــرين متــر ًا وخمســة وأربعــن ســنتم ويحدهــا طريــق‬\n     ‫عــرض مــن ‪ 5.20‬م إلــى ‪8‬م يليــه مرمــى عرضــه‪ 1.50‬م إلــى ‪ 20.1‬م يليــه‬\n\n\n‫‪61‬‬\n\f‫نخــل ‪ ،........‬جنوبـ ًا بطــول ثمانيــة وخمســن متــر ًا وســبعة وثالثــن ســنتم‬\n‫ويحــده مرمــى عرضــه‪3‬م يليــه شــارع ترابــي عرضــه‪20‬م إلــى ‪ 25‬م يليــه‬\n‫مرمــى عرضــه ‪2‬م يليــه أرض ‪ ،‬شــرق ًا مــن الشــمال باجتــاه اجلنــوب بطــول‬\n‫ســتة وأربعــن متــر ًا ويســتمر للجنــوب بطــول مائــة وأربعــة وعشــرين متــر ًا‬\n‫ال للجنوب الشــرقي‬      ‫ال قلي ً‬\n                              ‫وثالثــة وتســعني ســنتم ثــم ينعطــف للجنــوب مائ ً‬\n‫ا‬ ‫بطــول واحــد وعشــرين متــر ًا وأربعــن ســنتم ثــم ينعطــف للجنــوب مائـ ً‬\n‫للجنــوب الغربــي بطــول تســعة وتســعني متــر ًا وســبعة وســبعني ســنتم‬\n‫ويســتمر إلــى نهايــة احلــد بطــول مائــة وخمســة وعشــرين متــر ًا ويحــده‬\n‫مرمــى عرضــه يتــراوح مــن ‪ 1.50‬م إلــى‪4.0‬م يليــه طريــق ترابــي مختلــف‬\n‫االتســاع يتــراوح عرضــه مــن ‪6.7‬م إلــى ‪ 15.0‬م يفصــل شــارع عــرض ‪8‬م‬\n‫يلــي املرمــى ابتــداء مــن الشــمال نخــل ‪ ........‬ثــم نخــل ‪ ........‬بينهمــا مرمــى‬\n‫عرضــه ‪2‬م ثــم لنهايــة احلــد أرض ل‪ ........‬يفصــل بــن نخــل ‪ ......‬وأرض‬\n‫‪ ........‬مرمــى عــرض ‪1.50‬م وشــارع عــرض ‪8.0‬م ومرمــى عرض ‪1.50‬م‪،‬‬\n‫ا بطــول مائــة وأحــد عشــر‬     ‫ا للغــرب قلي ـ ً‬‫غرب ـ ًا ‪ :‬يبــدأ مــن الشــمال مائ ـ ً‬\n‫متــر ًا وخمســة وخمســن ســنتم ثــم بنفــس االجتــاه بطــول ثمانيــة وعشــرين‬\n‫متــر وأربعــة وثمانــن ســنتم ثــم بنفــس االجتــاه بطــول ثالثــة وســتني متــر ًا‬\n‫وثالثــن ســنتم ثــم ينعطــف للجنــوب وإلــى نهايــة احلــد بطــول مائتــن وســتة‬\n‫وعشــرين متــر ًا وســبعة وثمانــن ســنتم ويحــده مرمــى مختلــف االتســاع‬\n‫يتــراوح عرضــه مــن ‪1.50‬م إلــى ‪3.0‬م يليــه نخــل القابــل ومســاحته‬\n‫اإلجماليــة اثنــن وثالثــن ألف ـ ًا ومائتــان وثالثــة وعشــرين متــر ًا مربع ـ ًا‬\n‫وثالثــة يف املائــة مــن املتــر املربــع ‪ .‬ومــا عليهــا مــن إحيــاءات حســب إرثهــم‬\n‫الشــرعي والربــع األخيــر ألمــاك الدولــة شــائع يف عامــة األرض ‪ .‬ثــم‬\n‫طلبــت صــك حصــر الورثــة فأبــرزه املدعــي وكالــة وباالطــاع عليــه وجد‬\n\n\n                                                                                            ‫‪62‬‬\n\f     ‫أنــه صــادر مــن دائــرة األوقــاف واملواريــث مبحافظــة القطيــف برقــم‬\n     ‫‪........‬يف ‪1422/11/16‬ه ـ واملتضمــن ثبــوت وفــاة ‪ .....‬بتاريــخ‬\n     ‫‪1418/12/19‬ه ـ وانحصــار إرثــه يف أوالده وبناتــه وهــم ‪ .....‬ويف زوجتــه‬\n     ‫فقــط ثــم رفعــت اجللســة مــن أجــل االستفســار عــن ســريان مفعــول الصــك‬\n     ‫ويف جلســة أخــرى حضــر الطرفــان هــذا وقــد ورد اجلــواب مــن ســجالت‬\n     ‫احملكمــة برقــم ‪ 331269780‬يف ‪1433/7/12‬ه ـ ويتضمــن‪ :‬أن ســجل‬\n     ‫الصــك املرفقــة صورتــه مطابــق ملــا حوتــه الصــورة وهــو ســاري املفعــول‬\n     ‫اهــ‪ .‬ثــم أبــرز املدعــى عليــه ورقــة هــذا نصها‪ ( :‬بســم اهلل الرحمن الرحيم‬\n     ‫وجــه بيــان‪ :‬احلمــد هلل وحــده والصــاة علــى مــن ال نبــي بعــده وعلــى آلــه‬\n     ‫وصحبــه امليامــن والســام ‪ ،‬ليكــون معلوم ـ ًا ملــن يــراه انــه قــد بــاع‬\n     ‫الرجــل ‪ .....‬مــن أهالــي قريــة ‪........‬ســعودي باحلفيظــة رقم‪/‬وتاريــخ‬\n     ‫‪ 1379/1/23‬ســجل القطيــف وبســجل مدنــي ‪ -‬كامــل حصتــه مــن‬\n     ‫النخــل املســمى ( ‪ )........‬الكائــن يف قريــة ‪........‬والعائــد لــه بــاإلرث مــن‬\n     ‫ا خيــار فيــه وال نــذر متبوع ـ ًا بإقســاط جملــة‬   ‫والــده ‪ ،‬بيع ـ ًا بت ـ ًا وفص ـ ً‬\n     ‫الدعــاوى املســموعة وال ســيما دعــوى الغــن والغــدر واملواطــأة وأميانهــا‬\n     ‫هلل تعالــى ‪ ،‬مببلــغ وقــدره ســبعة وعشــرون ألــف ريــال ســعودي ‪ .‬وقــد‬\n     ‫شــراه املدعــو ‪ . .....‬مــن أهالــي ‪........‬ســعودي باحلفيظــة رقــم وتاريــخ‬\n     ‫‪ 1399/1/26‬ســجل القطيــف وقــد قبــض البائــع الثمــن بكمالــه ومتامــه‬\n     ‫( ‪ ) 27000‬ألــف ريــال مبجلــس املبيــع وبــه لــم يبــق البائــع يف املبيــع‬\n     ‫املذكــور وال يف ثمنــه لقبضــه إيــاه حــق وال مســتحق ‪ ،‬بــل صــار ذلــك ما ًال‬\n     ‫وملــك ًا للمشــتري املذكــور يتصــرف فيــه كيــف شــاء وأحــب وأراد‬\n     ‫كتصــرف املالكــن يف أمالكهــم وذوي احلقوق يف حقوقهم ال مصارع‬\n     ‫لــه فيــه وال منــازع حتــى ال يخفــى وأذن ملــن يشــهد واهلل خيــر الشــاهدين‬\n\n\n‫‪63‬‬\n\f‫‪ .‬حــرر يف غــرة صفــر عــام ‪1420‬ه ـ وقــد ذيلــت الورقــة بتوقيــع منســوب‬\n‫للشــاهد األول‪ :‬رقــم حفيظــة‪ :‬تاريخهــا ‪1409/11/22‬ه ـ ســجل القطيف‬\n‫وتوقيــع منســوب للشــاهد الثانــي‪ :‬رقــم حفيظــة‪ :‬يف ‪1395/11/15‬ه ـ‬\n‫ســجل القطيــف وتوقيــع منســوب ل‪13093/4/12 /........23........‬وختــم‬\n‫شــخصي غيــر واضــح مــكان توقيــع البائــع رقــم حفيظــة‪........ :‬بتاريــخ‪:‬‬\n‫‪1379/1/23‬ه ـ ســجل القطيــف‪. ) .‬أهــ‪ .‬ثــم قــال إنــه بعــد أن حضرنــا إلى‬\n‫كاتــب العــدل بهــذه الورقــة أفادنــا بأنــه ال يوجــد صــك لهــذا النخــل‬\n‫فخرجنــا مــن عنــده ولــم نتفــق علــى هــذه املبايعــة وأنــا لــم أســتلم شــيئ ًا مــن‬\n‫املدعــي علــى اإلطــاق وبعــرض هــذه الورقــة ومــا قــرره املدعــى عليــه‬\n‫علــى املدعــي وكالــة أجــاب قائ ـاً‪ :‬هــذه الورقــة صحيحــة ومــا ذكــره‬\n‫املدعــى عليــه هــو إقــرار بصحــة الورقــة هكــذا أجــاب ثــم رفعــت اجللســة‬\n‫للتأمــل ويف جلســة أخــرى حضــر الطرفــان ثــم ســألتهما هــل النخــل محــل‬\n‫الدعــوى اململــوك بالصــك رقــم ‪........‬يف ‪1428/2/20‬ه ـ هــو نفس النخل‬\n‫املشــار إليــه يف هــذه الورقــة فقــاال ‪ :‬نعــم ‪ .‬ثــم ســألت املدعــي وكالــة هــل‬\n‫ســلم موكلــك ثمــن النخــل الــذي اشــتراه للمدعــى عليــه فقــال ‪ :‬نعــم ‪.‬‬\n‫فســألته هــل لديــك بينــة علــى دعــواك فقــال ‪ :‬نعــم لــدي بينــة ومســتعد‬\n‫بإحضارهــا يف اجللســة القادمــة ثــم رفعــت اجللســة مــن أجــل ســماع بينــة‬\n‫املدعــي وكالــة ويف جلســة اخــرى حضــر املدعــي وكالــة وحضــر‬\n‫حلضــوره املدعــى عليــه وبســؤال املدعــي وكالــة عــن بينتــه التــي وعــد بهــا‬\n‫أجــاب قائ ـاً‪ :‬نعــم أحضرتهــا ويف هــذه اجللســة حضــر كل مــن ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم و‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم وبســؤال الشــاهد األول عــن عمــره وعملــه‬\n‫ومحــل اقامتــه وصلتــه باخلصــوم قــال‪ :‬إن عمــري قرابــة الســتني ســنة وأنــا‬\n\n\n                                                                                             ‫‪64‬‬\n\f     ‫متقاعــد مــن شــركة أرامكــو وأســكن يف ‪........‬مبحافظــة القطيــف‬\n     ‫وأنــا أخ للمدعــي واملدعــى عليــه وبســؤاله عمــا لديــه مــن شــهادة قــال‪:‬‬\n     ‫أشــهد هلل تعالــى بــأن املدعــي ‪........‬قــد أخبرنــي بأنــه اشــترى مــن املدعــى‬\n     ‫عليــه ‪........‬نصيبــه مــن النخــل املســمى ‪........‬واآليــل لــه وجلميــع إخوتــه‬\n     ‫ـاإلرث مــن مورثنــا بثمــن قــدره ســبعة وعشــرون ألــف ريـ(‪ )27000‬ــال وال‬  ‫بـ ً‬\n     ‫أعلــم هــل اســتلم البائــع الثمــن أم ال ‪ .‬هكــذا شــهد ‪ .‬وبســؤال الشــاهد‬\n     ‫الثانــي عــن عمــره وعملــه ومحــل اقامتــه وصلتــه باخلصــوم قــال‪ :‬إن عمري‬\n     ‫قرابــة اخلمســن ســنة وأنــا متقاعــد مــن شــركة الكهربــاء وأســكن يف‬\n     ‫‪........‬مبحافظــة القطيــف وأنــا أخ للمدعــي واملدعــى عليــه وبســؤاله عمــا‬\n     ‫لديــه مــن شــهادة قــال‪ :‬أشــهد هلل تعالــى بــأن املدعــى عليــه قــد بــاع نصيبه‬\n     ‫ـاإلرث مــن مورثنــا‬\n                    ‫ً‬      ‫مــن النخــل املســمى ‪........‬واآليــل لــه وجلميــع إخوتــه بـ‬\n     ‫علــى املدعــي بثمــن قــدره ســبعة وعشــرون ألــف (‪ )27000‬ريــال اســتلم‬\n     ‫ا وكان ذلــك قبــل أكثــر مــن ثمــان ســنوات‬       ‫املدعــى عليــه الثمــن كامـ ً‬\n     ‫وهــي نفــس النخــل التــي صــدر بهــا صــك مــن احملكمــة فيمــا بعــد‬\n     ‫ـاهد ًا ثالث ـ ًا هــو ســعودي‬\n                                ‫هكــذا شــهد ‪ .‬ثــم أحضــر املدعــي وكالــة شـ ً‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال عــن عمــره وعملــه ومحــل‬\n     ‫اقامتــه وصلتــه باخلصــوم قــال إن عمــري ســتون عامــا وأنــا متقاعــد مــن‬\n     ‫شــركة أرامكــو وأســكن يف ‪ ........‬مبحافظــة القطيــف واملدعــي‬\n     ‫واملدعــى عليــه أخــوان لزوجتــي وبســؤاله عمــا لديــه مــن شــهادة قــال‬\n     ‫أشــهد هلل تعالــى بــأن املدعــي ‪........‬قــد أخبرنــي بأنــه اشــترى مــن املدعــى‬\n     ‫ـاإلرث‬\n      ‫عليــه نصيبــه مــن النخــل املســمى ‪........‬واآليــل لــه وجلميــع إخوتــه بـ ً‬\n     ‫مــن مورثنــا علــى املدعــي بثمــن قــدره ســبعة وعشــرون ألــف (‪)27000‬‬\n     ‫ريــال وال أعلــم هــل اســتلم البائــع الثمــن أم ال هكــذا شــهد وبعــرض‬\n\n\n‫‪65‬‬\n\f‫الشــهود وشــهادتهم علــى املدعــى عليــه أجــاب قائ ـاً‪ :‬شــهادتهم غيــر‬\n‫صحيحــة وهــم لــم يشــاهدوا أي مبالــغ مســتلمة وال أقــول فيهــم شــيئ ًا إال‬\n‫أنهــم كذبــوا يف شــهادتهم هــذه ‪ .‬ثــم طلبــت مــن املدعــي وكالــة إحضــار‬\n‫مــن يزكــي الشــهود فاســتعد بذلــك ورفعــت اجللســة مــن أجــل إحضــار‬\n‫املزكيــن ويف جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره‬\n‫املدعــى عليــه فجــرى ســؤال املدعــي وكالــة عــن املزكــن فقــال نعــم‬\n‫أحضرتهــم ويف هــذه اجللســة حضــر وبســؤالهم عمــا لديهــم قالــوا نشــهد‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى‬     ‫بعدالــة وأمانــة وثقــة الشــاهدين‪ .‬فبنـ ً‬\n‫واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر بصحــة الورقــة املتضمنــة بيــع‬\n‫نصيبــه مــن العقــار محــل الدعــوى للمدعــي ‪........‬واســتالمه كامــل‬\n‫الثمــن واإلقــرار حجــة قاصــرة وال عــذر ملــن أقــر ‪ .‬ومــا دفــع بــه مــن عــدم‬\n‫إمتــام املبايعــة وعــدم اســتالمه للثمــن يعــد رجوعـ ًا عــن اإلقــرار مبــا جــاء يف‬\n‫هــذه الورقــة مــن ثبــوت املبايعــة وقــد نــص أهــل العلــم علــى أنــه ال يصــح‬\n‫الرجــوع عــن اإلقــرار بحــق آلدمــي ويقــوي ثبــوت هــذه املبايعــة وصحتهــا‬\n‫شــهادة الشــاهد ‪ .....‬املعــدل شــرع ًا ولقولــه تعالــى‪ ( :‬يأيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود ) لذلــك كلــه فقــد ثبــت لــدي صحــة بيــع املدعــى عليــه‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم نصيبــه مــن العقــار محــل الدعــوى‬\n‫للمدعــي وألزمــت املدعــى عليــه برفــع يــده عــن العقــار محــل الدعــوى‬\n‫وتســليمه للمدعــي أصالــة وبــه حكمــت وأمــرت بالتهميــش بذلــك علــى‬\n‫صــك العقــار بعــد اكتســاب احلكــم القطعيــة وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي وكالــة القناعــة باحلكــم كمــا قــرر املدعــى‬\n‫عليــه عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف واســتعد بتقــدمي‬\n‫الئحــة اعتراضيــة فأفهمتــه بــأن لــه أن يتقــدم بالئحتــه يف مــدة أقصاهــا‬\n\n\n                                                                                           ‫‪66‬‬\n\f     ‫ثالثــون يوم ـ ًا مــن تاريــخ اســتالمه نســخة مــن صــك احلكــم وهــو يــوم‬\n     ‫الســبت ‪1434/1/17‬ه ـ حــرر يف ‪1434/1/6‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                                   ‫محمد و على آله وصحبه وسلم ‪.‬‬\n     ‫احلمد هلل وحده وبعد يف يوم االربعاء ‪1434/4/10‬هـ فتحت اجللسة بناء‬\n     ‫على املعاملة الواردة لهذه احملكمة برقم ‪ 34796061‬يف ‪1434/4/1‬هـ‬\n     ‫بكتــاب ســماحة رئيــس محكمــة االســتئناف باملنطقــة الشــرقية رقــم‬\n     ‫‪ 34647146‬يف ‪1434/3/28‬ه وبرفقــه قــرار أصحــاب الفضيلــة قضــاة‬\n     ‫الدائــرة احلقوقيــة األولــى رقــم ‪ 34169561‬يف ‪1434/3/23‬ه ـ املتضمــن‬\n     ‫نــص احلاجــة منــه مــا يلــي‪ :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل ولــي‬\n     ‫التوفيــق اه ـ ‪ .‬قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف ختمــه‬\n     ‫وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وصحبــه وســلم ‪ ،‬ولبيانــه حــرر يف ‪1434/4/10‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪ 34647146‬وتاريــخ ‪ 1434/3/15‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم ‪33898829‬‬\n     ‫وتاريــخ ‪1434/ 3/9‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ ‪ ....‬املســجل برقــم ‪ 3414136‬وتاريــخ ‪1434/1/17‬ه ـ‬\n     ‫بشــأن دعــوى ‪ ....‬ضــد‪ ....‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n     ‫فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n     ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                            ‫حــرر يف‪1434/3/23‬ه ـ ‪.‬‬\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":59,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fedf9ea8cc0a0d33235debcd72a4b8625c4ba7e1c33140d2595fdb79ffa829a8","normalized_text_hash":"faf3478749bad69d64e4182400a98a934413828a992f51505e154851f9135173","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p59-3414136"}]$archive_payload$::jsonb) AS x LIMIT 25
